window.KB_BODY_RU=window.KB_BODY_RU||{};
window.KB_BODY_RU[14]={"20-018-016":"<h3>Спецификации</h3><p>с форсункой электронного управления</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Для значений производительности и расхода топлива обратитесь к спецификации двигателя или коду топливного насоса для конкретного рейтинга.</p></div></div><h4>Двигатель Idle Speed</h4><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Двигатель Idle Speed</th><th>См. таблицу данных двигателя</th></tr></thead><tbody></tbody></table></div><h4>Максимальное ограничение входного топливного бака</h4><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Грязный топливный фильтр</th><th>34кПа[10 in-Hg]</th></tr></thead><tbody></tbody></table></div><h4>Сопротивление магистрали слива топлива:</h4><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>С помощью Check клапанs</th><th>127 мм рт.ст. [5 in-Hg]</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>С помощью Check клапанs удалены</th><th>254 мм рт.ст. [10 in-Hg]</th></tr></thead><tbody></tbody></table></div><h4>Удаление воды:</h4><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>бесплатно</th><th>95%</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>эмульгированный</th><th>95%</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Минимальная скорость вращения двигателя</th><th>150 об/мин</th></tr></thead><tbody></tbody></table></div><p>с форсункой механического управления</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Для значений производительности и расхода топлива обратитесь к спецификации двигателя или коду топливного насоса для конкретного рейтинга.</p></div></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Двигатель Idle Speed</th><th>600 - 1400 об/мин</th></tr></thead><tbody></tbody></table></div><h4>Максимальное ограничение впуска топлива:</h4><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Чистый топливный фильтр</th><th>100 мм рт.ст. [4.0 in-Hg]</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Грязный топливный фильтр</th><th>203 мм рт.ст. [8.0 in-Hg]</th></tr></thead><tbody></tbody></table></div><h4>Сопротивление магистрали слива топлива:</h4><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>С помощью Check клапанs</th><th>0 - 21 кПа[0 - 3 psi]</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>С помощью Check клапанs удалены</th><th>14-34 кПа[2-5 psi]</th></tr></thead><tbody></tbody></table></div><h4>Проверка клапана между топливным насосом и головкой цилиндра (неотъемлемой для топливного насоса):</h4><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Давление при открытии</th><th>21-35 кПа[3-5 psi]</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Минимальная скорость вращения двигателя</th><th>150 об/мин</th></tr></thead><tbody></tbody></table></div><h4>Проверка клапана на линии подачи топлива:</h4><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Давление при открытии</th><th>13-25 мм рт.ст. [1/4 до 1/2 psi]</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Скорость топлива для двигателя на высокой высоте</th><th>4% на 300 м [1000 футов] выше 3600 м [12000 футов]</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Сокращение расхода топлива для двигателя в жаркую погоду</th><th>2% на 11°C выше 38°C [1% на 10°F выше 100°F]</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Сопротивление соленоидной катушки клапан в омах 24 VDC</th><th>28-32 Ом</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Давление накачки топлива - минимальное</th><th>172 кПа[25 psi] при 150 об/мин</th></tr></thead><tbody></tbody></table></div><h4>Давление топливного насоса - минимальное (при измерении двигателя):</h4><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>1500 об/мин</th><th>1448 кПа[210 psi]</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>1800 об/мин</th><th>1655 кПа[240 psi]</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>2100 об/мин</th><th>1861 kPa[270 psi]</th></tr></thead><tbody></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>2350 об/мин</th><th>1999 kPa[290 psi]</th></tr></thead><tbody></tbody></table></div>","28-000-001-tr":"<h3>Подготовительные операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Охлаждающая жидкость токсична. Держитесь подальше от маленьких детей и домашних животных. Если деталь не используется повторно, утилизируйте её по местным природоохранным требованиям.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Не снимайте пробку радиатора с горячего двигателя. Снимайте пробку радиатора только после того, как температура охлаждающей жидкости опустится ниже 50 °C [120 °F]. Струя горячей охлаждающей жидкости или пар могут привести к травме.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Чтобы снизить риск травмы, не допускайте попадания горячего масла на кожу.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>По заключению ряда государственных органов отработанное моторное масло может обладать канцерогенным действием и вредить репродуктивной функции. Не вдыхайте пары, не допускайте попадания внутрь и длительного контакта с отработанным моторным маслом. Если повторно не использовано, утилизировать в соответствии с местными экологическими нормами.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Масса этого узла больше 23 кг [50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><ul><li>Прикрепите теги ко всем шлангам, линиям, связям и электрическим соединениям, когда они удаляются, чтобы определить местоположение и помочь процессу установки.</li><li>Отсоедините провода аккумуляторных батарей.<a class=\"lnk doc\" href=\"#/doc/99-013-009\">См. процедуру 013-009 (Кабели и соединения аккумуляторов) в разделе 13.</a></li><li>Слить охлаждающую жидкость двигателя.<a class=\"lnk doc\" href=\"#/doc/28-008-018-tr\">См. процедуру 008-018 (Система охлаждения) в разделе 8.</a></li><li>Слить моторное масло. См. процедуру 007-037 (Система моторного масла) в разделе 7.</li></ul><ul><li>Прикрепите теги ко всем шлангам, линиям, связям и электрическим соединениям, когда они удаляются, чтобы определить местоположение и помочь процессу установки.</li><li>Отсоедините аккумуляторные батареи.<a class=\"lnk doc\" href=\"#/doc/99-013-009\">См. процедуру 013-009 (Кабели и соединения аккумуляторов) в разделе 13.</a></li><li>Отключите подачу воздуха/топлива к воздухозаборнику, если он оборудован. См. процедуру 012-022 (Воздушный пусковой двигатель) в разделе 12.</li><li>Слить охлаждающую жидкость двигателя. См. процедуру 008-018 (Система охлаждения) в разделе 8.</li><li>Смажьте моторное масло из двигателя. См. процедуру 007-037 (Система моторного масла) в разделе 7.</li><li>Отсоедините стартерный кабель, ремни заземления двигателя, кабину или шасси к шлангам двигателя, трубам, электрическим проводам и гидравлическим линиям.</li><li>Отключите все шланги, трубки, электрические провода и гидравлические линии, если они оборудованы.</li><li>Отсоедините трубы впускной и выхлопной системы. См. инструкции по установке OEM.</li><li>Отсоедините приводные агрегаты от корпуса маховика и маховика. См. сервисное руководство изготовителя машины.</li><li>Удалите линии кондиционирования воздуха, если это необходимо. См. сервисное руководство изготовителя машины.</li><li>Удалите все компоненты шасси, необходимые для удаления двигателя из оборудования. См. сервисное руководство изготовителя машины.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ck800wa.png\" alt=\"ck800wa.png\"></figure><h3>Снятие</h3><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Иллюстрации двигателя в этой процедуре могут быть разными для конкретного применения, но этапы удаления одинаковы независимо от типа двигателя.</p></div></div><p>Отсоедините стартерный кабель, ремни заземления двигателя, кабину или шасси к шлангам двигателя, трубам, электрическим проводам и гидравлическим линиям.</p><p>Отключите все шланги, трубки, электрические провода и гидравлические линии, если они оборудованы.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/13200042.png\" alt=\"13200042.png\"></figure><p>Отсоедините трубы впускной и выхлопной системы.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/oi400hc.png\" alt=\"oi400hc.png\"></figure><p>Отсоедините приводные агрегаты от корпуса маховика и маховика.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/tr400wa.png\" alt=\"tr400wa.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Если используется система жидкого хладагента (кондиционирование воздуха), используйте защиту глаз и лица и оберните ткань вокруг фитингов перед удалением. Жидкий хладагент может вызвать серьезные травмы глаз и кожи.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Для защиты окружающей среды системы жидких хладагентов должны быть надлежащим образом опорожнены и заполнены с использованием оборудования, которое предотвращает выброс хладагента в атмосферу. Федеральный закон требует улавливания и переработки хладагента.</p></div></div><p>Удалите линии кондиционирования воздуха, если это необходимо.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/oi800qb.png\" alt=\"oi800qb.png\"></figure><p>Удалите все компоненты шасси, необходимые для удаления двигателя из оборудования.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/00600043.png\" alt=\"00600043.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Масса этого узла больше 23 кг [50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Перед подъемом двигателя проверьте четыре кронштейна для подъема двигателя. Убедитесь, что каждая скобка содержит пятно под затвердевшей плоской стиральной машиной. Если скобка не имеет пятнистого лица, удалите болты. Проверьте на ржавчину и коррозию. Если болты имеют ржавчину или коррозию, замените болты перед подъемом двигателя. См. процедуру 016-001 (Подъемные скобки двигателя) в разделе 16. См. процедуру 016-001 (Подъемные скобки двигателя) в разделе 16.</p></div></div><p>Двигатели KTA38GC, K38 и QSK38 имеют четыре подъемных кронштейна, по два на каждом берегу. Подъемные кронштейны для K38 устанавливаются между цилиндрами номерами 1 и 2, а также 5 и 6.</p><p>Подъемные кронштейны для K50 и QSK50 устанавливаются между цилиндрами номерами 2 и 3, 6 и 7.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ew600li.png\" alt=\"ew600li.png\"></figure><p>Снимите подъемные скобки. Проверьте наличие трещин, ржавчины и коррозии. Установите подъемные скобки. См. процедуру 016-001 (Подъемные скобки двигателя) в разделе 16. См. процедуру 016-001 (Подъемные скобки двигателя) в разделе 16.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/16600023.png\" alt=\"16600023.png\"></figure><p>Подъемные приспособления для двигателя, номер детали 3163264, предназначены для подъёма двигателя <b> только </b>. Любые дополнительные компоненты, прилагаемые (в том числе к торцу привода, не приводному концу и/или шасси) **, должны быть удалены.</p><p>Подъемная сила ** должна быть в прямой вертикальной линии с подъемными скобками в обоих направлениях.</p><p>Подъемный механизм двигателя, номер детали 3163264, доступен от Cummins Inc. Данный крепеж доступен для подъема двигателей собранных KTA38GC, K38, K50, QSK38, QSK50.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/00600238.png\" alt=\"00600238.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не пытайтесь поднять двигатель с помощью устройства, которое позволяет боковую загрузку подъемных скобок, или позволяет цепи или кабеля приложить силу к другим частям двигателя. Подъемные скобки или детали могут разбиться, в результате чего двигатель падает и повреждается.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/00600239.png\" alt=\"00600239.png\"></figure><p><b> Всегда</b> Используйте подъемные кронштейны, которые соединены с базовыми рельсами, когда приводные агрегаты или радиатор установлены на базовых рельсах с двигателем.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/00600240.png\" alt=\"00600240.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Никогда не используйте кронштейны для подъема двигателя или крепление для подъема двигателя, часть 3163264, для подъема двигателя, когда приводные агрегаты или радиатор установлены на общих базовых рельсах. Никогда не используйте подъемную кронштейн на блоке для подъема двигателя, который установлен на базовых рельсах, когда на базовых рельсах также установлен приводной или радиатор. Подъемные скобки или детали могут разбиться, в результате чего двигатель падает. Повреждение двигателя может привести к</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ew600lf.png\" alt=\"ew600lf.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не пытайтесь поднять двигатель с помощью устройства, которое позволяет боковую загрузку подъемных скобок, или позволяет цепи или кабеля приложить силу к другим частям двигателя. Подъемные скобки или детали могут разбиться, в результате чего двигатель падает и повреждается.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/00600241.png\" alt=\"00600241.png\"></figure><h3>Завершающие операции</h3><p>Покрыть все отверстия двигателя, чтобы предотвратить попадание грязи и мусора в двигатель.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/tb4otla.png\" alt=\"tb4otla.png\"></figure><p>Удалите все оставшиеся аксессуары и скобки, которые будут использоваться на заменяющем двигателе.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ew400hc.png\" alt=\"ew400hc.png\"></figure>","28-000-002-tr":"<h3>Подготовительные операции</h3><p>Установите все аксессуары и скобки, которые были сняты с двигателя.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ew400hc.png\" alt=\"ew400hc.png\"></figure><p>Откройте все отверстия двигателя.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/tb4otla.png\" alt=\"tb4otla.png\"></figure><h3>Установка</h3><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Никогда не используйте кронштейны для подъема двигателя или крепление для подъема двигателя, часть 3163264, для подъема двигателя, когда приводные агрегаты или радиатор установлены на общих базовых рельсах. Никогда не используйте подъемную кронштейн на блоке для подъема двигателя, который установлен на базовых рельсах, когда на базовых рельсах также установлен привод или радиатор. Подъемные скобки или детали могут разбиться, в результате чего двигатель падает. Повреждение двигателя может привести к</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ew600lf.png\" alt=\"ew600lf.png\"></figure><p><b> Всегда</b> Используйте подъемные кронштейны, которые соединены с базовыми рельсами, когда приводные агрегаты или радиатор установлены на базовых рельсах с двигателем.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/00600240.png\" alt=\"00600240.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не пытайтесь поднять двигатель с помощью устройства, которое позволяет боковую загрузку подъемных скобок, или позволяет цепи или кабеля приложить силу к другим частям двигателя. Подъемные скобки или детали могут разбиться, в результате чего двигатель падает и повреждается.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/00600239.png\" alt=\"00600239.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Перед подъемом двигателя проверьте четыре кронштейна для подъема двигателя. Убедитесь, что каждая скобка содержит пятно под затвердевшей плоской стиральной машиной. Если скобка не имеет пятнистого лица, удалите болты. Проверьте на ржавчину и коррозию. Если болты имеют ржавчину или коррозию, замените болты перед подъемом двигателя.</p></div></div><p>Двигатели KTA38GC, K38 и QSK38 имеют четыре подъемных кронштейна, по два на каждом берегу. Подъемные кронштейны устанавливаются между цилиндрами номерами 1 и 2, а также 5 и 6.</p><p>Подъемные кронштейны для K50 устанавливаются между цилиндрами номерами 2 и 3, а также 6 и 7.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ew600li.png\" alt=\"ew600li.png\"></figure><p>Снимите подъемные скобки. Проверьте наличие трещин, ржавчины и коррозии. Установите подъемные скобки. См. процедуру 016-001 (Подъемные скобки двигателя) в разделе 16.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/16600023.png\" alt=\"16600023.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Масса этого узла больше 23 кг [50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><p>Подъемные приспособления для двигателя, номер детали 3163264, предназначены для подъёма двигателя <b> только </b>. Любые дополнительные компоненты, прилагаемые (в том числе к торцу привода, не приводному концу и/или шасси) **, должны быть удалены.</p><p>Подъемная сила ** должна быть в прямой вертикальной линии с подъемными скобками в обоих направлениях.</p><p>Подъемный механизм двигателя, номер детали 3163264, доступен от Cummins Inc. Данный крепеж доступен для подъема двигателей собранных KTA38GC, K38, K50, QSK38, QSK50.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/00600238.png\" alt=\"00600238.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Масса этого узла больше 23 кг [50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><p>Используйте правильно оцененный подъемник и крепление для подъема двигателя № 3163264 для установки двигателя.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/00600042.png\" alt=\"00600042.png\"></figure><p>С установленным двигателем проверьте конечный зазор коленчатого вала, чтобы убедиться, что он все еще находится в пределах спецификации.<a class=\"lnk doc\" href=\"#/doc/28-001-007-tr\">См. процедуру 001-007 в разделе 1.</a></p><p>Удалите доступную крышку ручного отверстия. См. процедуру 001-035 в разделе 1. Кранкшафт можно перемещать вперед и назад, используя прыжок на паутине коленчатого вала через отверстие крышки ручного отверстия. Конечный зазор можно измерить через отверстие крышки ручного отверстия на противовесе коленчатого вала или на переднем демпфере.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Не используйте на амортизаторе прыжок для перемещения коленчатого вала. Это может привести к повреждению демпфера.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Масляная поддона показана удаленной из двигателя для иллюстративных целей.</p></div></div><p>После подтверждения того, что конечный зазор находится в пределах спецификации, замените крышку ручного отверстия. См. процедуру 001-035 в разделе 1. Если конечный зазор выходит за установленные пределы, проверьте несоответствие с прилагаемыми приводными устройствами.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb1beja.png\" alt=\"mb1beja.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Осмотрите кронштейны для подъема двигателя на предмет повреждения или трещин. Не пытайтесь поднять двигатель, если видны какие-либо трещины или повреждения. Использование поврежденного подъемного оборудования может привести к серьезным травмам и / или имущественному ущербу.</p></div></div><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Убедитесь, что все линии, шланги и трубы находятся в хорошем состоянии, правильно нанесены и закреплены, чтобы предотвратить повреждение двигателя.</p></div></div><p>Выровняйте двигатель в шасси на базовых рельсах, а также затяните болты крепления двигателя. См. спецификации крутящего момента OEM.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/00600040.png\" alt=\"00600040.png\"></figure><h3>Завершающие операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Охлаждающая жидкость токсична. Держитесь подальше от маленьких детей и домашних животных. Если деталь не используется повторно, утилизируйте её по местным природоохранным требованиям.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Не снимайте пробку радиатора с горячего двигателя. Снимайте пробку радиатора только после того, как температура охлаждающей жидкости опустится ниже 50 °C [120 °F]. Струя горячей охлаждающей жидкости или пар могут привести к травме.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Чтобы снизить риск травмы, не допускайте попадания горячего масла на кожу.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>По заключению ряда государственных органов отработанное моторное масло может обладать канцерогенным действием и вредить репродуктивной функции. Не вдыхайте пары, не допускайте попадания внутрь и длительного контакта с отработанным моторным маслом. Если повторно не использовано, утилизировать в соответствии с местными экологическими нормами.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Масса этого узла больше 23 кг [50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><ul><li>Заполните двигатель чистым моторным маслом. См. процедуру 007-037 в разделе 7.</li></ul><ul><li>Заполните систему охлаждения охлаждающей жидкостью.<a class=\"lnk doc\" href=\"#/doc/28-008-018-tr\">См. процедуру 008-018 в разделе 8.</a></li><li>Подключите подачу воздуха к воздухозаборнику, если он оборудован.<a class=\"lnk doc\" href=\"#/doc/102-012-022\">См. процедуру 012-022 в разделе 12.</a></li><li>Установите линии кондиционирования воздуха, если это необходимо. См. сервисное руководство изготовителя машины.</li><li>Подключите трубы впускной и выхлопной системы. См. сервисное руководство изготовителя машины.</li><li>Установите все компоненты шасси, необходимые для установки двигателя на оборудование. См. сервисное руководство изготовителя машины.</li><li>Подключите стартерный кабель, ремни заземления двигателя, кабину или шасси к шлангам двигателя, трубам, электрическим проводам и гидравлическим линиям.</li><li>Подсоедините провода аккумуляторных батарей. См. сервисное руководство изготовителя машины.</li><li>Проведите окончательный осмотр, чтобы убедиться, что все шланги, провода, соединения и компоненты были правильно установлены и затянуты.</li><li>Работайте с двигателем на низком холостом ходу в течение 2-3 минут.</li><li>Остановите двигатель и подождите 5-7 минут, пока масло сливается в масляную кастрюлю. Проверьте уровень масла и охлаждающей жидкости снова.</li><li>Заполните двигатель до нужного уровня масла и охлаждающей жидкости, если это необходимо. См. процедуру 007-037 в разделе 7.<a class=\"lnk doc\" href=\"#/doc/28-008-018-tr\">См. процедуру 008-018 в разделе 8.</a></li><li>Управляйте двигателем в течение 8-10 минут, чтобы проверить правильность работы, необычные шумы и утечки охлаждающей жидкости, топлива и моторного масла. См. процедуру 014-006 в разделе 14.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ck800wa.png\" alt=\"ck800wa.png\"></figure>","28-001-003-tr":"<h3>Выбор сервисного инструмента</h3><h4>Рекомендованный сервисный инструмент Cummins®</h4><ul><li>Комплект установки Drive Seal, номер детали 5573466</li></ul><h4>Дополнительные сервисные позиции</h4><ul><li>Маллетт</li></ul><h3>Подготовительные операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><ul><li>Удалите шкив из вспомогательного приводного вала.<a class=\"lnk doc\" href=\"#/doc/28-009-004-tr\">См. процедуру 009-004 в разделе 9.</a></li><li>Отсоедините аккумуляторные батареи.<a class=\"lnk doc\" href=\"#/doc/99-013-009\">См. процедуру 013-009 в разделе 13.</a></li><li>Отключите подачу воздуха/газа на стартер, если он оборудован. См. процедуру 012-022 в разделе 12.</li><li>Удалите шкив из вспомогательного приводного вала. См. процедуру 009-004 в разделе 9.</li></ul><h3>Снятие</h3><p>Используйте латунный дрейф, чтобы удалить ключ (3) от древесного волокна из вала.</p><p>Удалить печать на ключе.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/dp6puma.png\" alt=\"dp6puma.png\"></figure><p>Удалите старую уплотнение приводного вала аксессуара с крышки корпуса передней передачи.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600317.png\" alt=\"01600317.png\"></figure><h3>Установка</h3><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Если двигатель <b> не</b> имеет шкив на вспомогательном приводном вале, <b> будет установлена только</b> крышка. См. процедуру 009-039 в разделе 9.</p></div></div><p>Используйте установщик печати, номер детали 5573467. Установите уплотнение привода аксессуара.</p><p>Нажмите уплотнение на крышку, пока фланж инструмента не остановится на крышке передач.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01100186.png\" alt=\"01100186.png\"></figure><p>Установите уплотнение (4) ключа и ключ для вала (5).</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/dp6puha.png\" alt=\"dp6puha.png\"></figure><h3>Завершающие операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><ul><li>Установите шкив на вспомогательную вал привода.<a class=\"lnk doc\" href=\"#/doc/28-009-004-tr\">См. процедуру 009-004 в разделе 9.</a>.</li><li>Запустите двигатель и проверьте на отсутствие утечек.</li><li>Установите шкив из вспомогательного приводного вала. См. процедуру 009-004 в разделе 9.</li><li>Подключите подачу воздуха/газа к стартеру, если он оборудован. См. процедуру 012-022 в разделе 12.</li><li>Подсоедините аккумуляторные батареи.<a class=\"lnk doc\" href=\"#/doc/99-013-009\">См. процедуру 013-009 в разделе 13.</a>.</li><li>Запустите двигатель и проверьте на отсутствие утечек.</li></ul>","28-001-005-tr":"<h3>Подготовительные операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>По заключению ряда государственных органов отработанное моторное масло может обладать канцерогенным действием и вредить репродуктивной функции. Не вдыхайте пары, не допускайте попадания внутрь и длительного контакта с отработанным моторным маслом. Если деталь не используется повторно, утилизируйте её по местным природоохранным требованиям.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Чтобы снизить риск травмы, не допускайте попадания горячего масла на кожу.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Этот компонент весит более 23 кг[50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><ul><li>Отсоедините аккумуляторные батареи. См. сервисную документацию изготовителя оборудования.</li><li>Слить моторное масло.<a class=\"lnk doc\" href=\"#/doc/28-007-025-tr\">См. процедуру 007-025 в разделе 7.</a></li><li>Удалите фильтры полного потока.<a class=\"lnk doc\" href=\"#/doc/28-007-013-tr\">См. процедуру 007-013 в разделе 7.</a></li><li>Снять сборку адаптера моторного масла.<a class=\"lnk doc\" href=\"#/doc/28-007-017\">См. процедуру 007-017 в разделе 7.</a></li><li>Удалите масляную всасывающую трубку и скобки, если это необходимо, для доступа к подшипникам шатуна.<a class=\"lnk doc\" href=\"#/doc/28-007-040-tr\">См. процедуру 007-040 в разделе 7.</a></li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ck800wa.png\" alt=\"ck800wa.png\"></figure><p>Используйте запорный механизм (3) для вращения коленчатого вала. Поместите шатуны вблизи нижнего центра для максимальной доступности при ослаблении соединительных болтов стержня.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600320.png\" alt=\"01600320.png\"></figure><h3>Снятие</h3><p>Устраняйте болты до тех пор, пока не будет приблизительно 6,0 мм [0,24 дюйма ] зазора между крышкой и головкой болтов.</p><p>Используйте мягкоголовый молоток, чтобы нажать болты поочередно, пока стержень не отделится от колпачка. Удалите болты и колпачок.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600321.png\" alt=\"01600321.png\"></figure><p>Удалите нижний подшипник стержня. Напишите положение подшипника в области танга, как показано, для повторного использования или анализа.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Шатуны имеют номер цилиндра и положение, отпечатанное на стороне стержня и колпачка, которая находится по направлению к распределительному валу. Проверьте стержни и колпачки для правильной маркировки.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600322.png\" alt=\"01600322.png\"></figure><p>Подтолкните стержни достаточно далеко, чтобы позволить верхним подшипникам быть удаленными. Отметьте число цилиндров и местоположение в области танга, как описано, для нижнего подшипника.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Рекомендуется использовать соединительные штифты направляющих штифтов или эквивалентные, чтобы предотвратить повреждение журнала.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600323.png\" alt=\"01600323.png\"></figure><h3>Очистка и проверка при повторном использовании</h3><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Если замена подшипника была инициирована из-за неисправности, проверьте масляную поддон для мусора. Если присутствует значительный мусор, удалите и разберите масляный насос смазки и проверьте втулки на предмет повреждения мусора.<a class=\"lnk doc\" href=\"#/doc/28-007-031-tr\">См. процедуру 007-031 в разделе 7.</a></p></div></div><p>Очистите журнал коленчатого вала без винта тканью и проверьте журнал на предмет повреждений.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600324.png\" alt=\"01600324.png\"></figure><p>Очистить шатун и колпачок с помощью безлипкой ткани. Осмотрите колпачок, седло и болты для никсов, трещин, заусенцев, царапин или трения.</p><p>Если ника в области седла можно <b>не</b> удалить с помощью кроковой ткани, стержень *** должен быть заменен.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx8behf.png\" alt=\"cx8behf.png\"></figure><p>Подшипники <b> должны быть помечены для определения местоположения, поскольку они удаляются для будущей идентификации. Каждый подшипник </b> должен быть установлен в своем первоначальном месте, если подшипник установлен снова.</p><p>Используйте писцовую или шариковую ручку, чтобы отметить местоположение подшипника в области танга.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx1bema.png\" alt=\"cx1bema.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При использовании растворителей, кислот или щелочных материалов для очистки следуйте рекомендациям производителя по применению. Носите очки и защитную одежду, чтобы избежать травм.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При работе со сжатым воздухом применяйте защиту глаз и лица. Разлетающиеся частицы и грязь могут привести к травме.</p></div></div><p>Используйте растворитель для очистки подшипников.</p><p>Просушите сжатым воздухом.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx8beea.png\" alt=\"cx8beea.png\"></figure><p>Осмотрите подшипниковую поверхность спереди и сзади на предмет:</p><ul><li>Никс</li><li>Трещины</li><li>Бёрлз</li><li>Схватки (достаточно глубокие, чтобы их можно было почувствовать ногтем)</li><li>обрывки</li><li>Гугз</li><li>Встроенные частицы</li><li>фреттинг</li><li>Питтинг</li><li>хлопанье</li><li>Коррозия</li><li>Повреждение от замкового танга.</li></ul><p>Если обнаружено повреждение, подшипник *** должен быть заменен.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx2besa.png\" alt=\"cx2besa.png\"></figure><p>Нормальный износ подшипника производит гладкую отделку, которая будет носиться в медную подкладку. Обнаруженная медь <b> не всегда </b> указывает на изношенные подшипники. Ссылка на Руководство по повторному использованию частей, Вестник 3810303.</p><p>Если в подшипниках видны большие участки медной обшивки до того, как двигатель накопит 3000 часов, проверьте двигатель на предмет загрязнения мелкими частицами грязи и исправьте проблему.</p><p>Для получения более подробной информации о повреждении подшипника см. Руководство по анализу и предотвращению недержания, Вестник 3810387.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx8beba.png\" alt=\"cx8beba.png\"></figure><p>Используйте шаровой микрометр для измерения толщины подшипника в месте износа.</p><p>Заменить подшипник, если он <b> не</b> в пределах спецификаций.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Соединение Рода, несущего Толщину Стандарт или Размер</th><th></th><th></th><th></th></tr></thead><tbody><tr><td></td><td>мм</td><td></td><td>в</td></tr><tr><td>Стандартный стандарт</td><td>3.106</td><td>Мин</td><td>0.1223</td></tr><tr><td></td><td>3.157</td><td>Макс</td><td>0.1243</td></tr><tr><td>0,010 Размер</td><td>3.233</td><td>Мин</td><td>0.1273</td></tr><tr><td></td><td>3.284</td><td>Макс</td><td>0.1293</td></tr><tr><td>0,020 Размер</td><td>3.360</td><td>Мин</td><td>0.1323</td></tr><tr><td></td><td>3.411</td><td>Макс</td><td>0.1343</td></tr><tr><td>0,030 Размер</td><td>3.487</td><td>Мин</td><td>0.1373</td></tr><tr><td></td><td>3.538</td><td>Макс</td><td>0.1393</td></tr><tr><td>0,040 Размер</td><td>3.614</td><td>Мин</td><td>0.1423</td></tr><tr><td></td><td>3.665</td><td>Макс</td><td>0.1443</td></tr></tbody></table></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb8betb.png\" alt=\"mb8betb.png\"></figure><h3>Установка</h3><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Если подшипники должны быть повторно использованы, убедитесь, что они установлены в исходном месте.</p></div></div><p>Номера частей верхних и нижних новых подшипников ** должны быть идентичными.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600325.png\" alt=\"01600325.png\"></figure><p>Смазать верхний подшипник моторным маслом и установить его в шатун с тангом, прочно сидящим в машинном отсеке.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Подшипники для штанги доступны в размерах 0,010, 0,020, 0,030 и 0,040 дюйма. Если стержневые журналы были заземлены меньшего размера, то сумма будет штампована на противовесе, ближайшем к передней части двигателя.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600326.png\" alt=\"01600326.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не смазывайте заднюю часть несущих раковин.</p></div></div><p>Установите нижнюю оболочку подшипника в штангу. Убедитесь, что подшипник находится на месте в машинном слоте. Кроме того, убедитесь, что концы подшипников даже с раздвижными поверхностями.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx8behd.png\" alt=\"cx8behd.png\"></figure><p>Смазать соединительные болты стержня резьбой и шайбы моторным маслом и позволить избытку стекать.</p><p>Установите шайбы и болты в колпаки.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx8csha.png\" alt=\"cx8csha.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Соединяющие стержни и колпачки не являются взаимозаменяемыми, а колпачки укладываются только в одном направлении. Створки и колпачки обрабатываются в виде сборки, и в результате их сбоя происходит их смешивание.</p></div></div><p>Установите соединительные штанги. Убедитесь, что сторона крышки с потолком находится к филе журнала.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6caha.png\" alt=\"cx6caha.png\"></figure><p>Используйте следующие шаги, чтобы затянуть болты. Нанесите крутящий момент плюс угол на оба болта на шатуне.</p><p>Момент затяжки:</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Если при нанесении требуемого крутящего момента на соединительные болты стержня можно использовать калибр угла ****, то можно использовать следующую последовательность:</p></div></div><p>Используйте следующие шаги, чтобы затянуть болты.</p><p>Момент затяжки:</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6boha.png\" alt=\"cx6boha.png\"></figure><p>Освободите оба соединительных болта.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600327.png\" alt=\"01600327.png\"></figure><p>Используйте инструмент (1) соединительных болтов стержня, номер детали 3822764, и следующую процедуру для измерения растяжения болтов.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Использование двух инструментов уменьшает вероятность ошибки и требует меньше времени. Следующие шаги показывают использование одного инструмента.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6toga.png\" alt=\"cx6toga.png\"></figure><p>Поместите инструмент на первые болты стержня, как показано.</p><p>Убедитесь, что наковальня центрирована в отверстие болтов стержня, и инструмент правильно контактирует с головой.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6toha.png\" alt=\"cx6toha.png\"></figure><p>Убедитесь, что на индикаторе осталось как минимум 0,030 дюйма в сторону повышения.</p><p>Если есть <b>не</b> достаточное движение, ослабьте запирающие винты на дне инструмента и переместите наковальню вниз.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6toub.png\" alt=\"cx6toub.png\"></figure><p>Убедитесь, что инструмент находится в положении, и отрегулируйте циферблат индикатора до тех пор, пока игла не наберет отметку 0,050 дюйма.</p><p>Запишите значение как «первый болт ноль». Закрепите замок (2) на циферблате индикатора для поддержания считывания.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6toua.png\" alt=\"cx6toua.png\"></figure><p>Удалите инструмент из первого показаний и поместите его на другие болты того же стержня.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Нет необходимости в том, чтобы болты были одинаковой длины.</p></div></div><p>Запишите показания, полученные как «второй болт ноль».</p><p>Удалите инструмент.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6bota.png\" alt=\"cx6bota.png\"></figure><p>Затягивайте болты попеременно и равномерно. Используйте предыдущие значения крутящего момента в этой процедуре.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6boha.png\" alt=\"cx6boha.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p><b>Не</b> Настройте индикаторный циферблат.</p></div></div><p>Поместите инструмент на первые соединительные болты стержня и возьмите показания 1,78 мм [0,070 в].</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6botb.png\" alt=\"cx6botb.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p><b>Не</b> Настройте индикаторный циферблат.</p></div></div><p>Поместите инструмент на второй стержень болтов и возьмите показания.</p><p>Запишите значение как «второй болт плотно». В этом примере значение составляет 1,42 мм [0,056 в].</p><p>Удалите инструмент.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6botc.png\" alt=\"cx6botc.png\"></figure><p>Определите количество растяжения болтов, вычитая «нулевой болт» из значения «узкого болта» для каждого болта.</p><p>Вычислительные болты Stretch</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Вычислительные болты Stretch</th><th></th></tr></thead><tbody><tr><td>&quot;Первый болт плотно&quot; значение</td><td>0,070 дюйма</td></tr><tr><td>Значение «First bolt zero»</td><td>0,050 дюйма</td></tr><tr><td>«Первый болт растяжения»</td><td>= 0,020 дюйма</td></tr><tr><td>&quot;Второй болт плотно&quot; значение</td><td>0,056 дюйма</td></tr><tr><td>&quot;Второй болт ноль&quot; значение</td><td>0,045 дюйма</td></tr><tr><td>&quot;Второй болт растягивается&quot;</td><td>= 0,011 дюйма</td></tr></tbody></table></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6botd.png\" alt=\"cx6botd.png\"></figure><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Rod bolts Stretch Спецификация</th><th></th><th></th></tr></thead><tbody><tr><td>мм</td><td></td><td>в</td></tr><tr><td>0.343</td><td>Мин</td><td>0.0135</td></tr><tr><td>0.470</td><td>Макс</td><td>0.0185</td></tr></tbody></table></div><p>Если растяжение болтов больше, чем спецификация, ослабьте оба болта, а также удалите и отбросьте тот, который был больше спецификации.</p><p>Установите новые болты с использованием указанных шагов крутящего момента и повторите процедуру измерения растяжения болтов, предполагая, что другие болты были в пределах спецификаций.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600325.png\" alt=\"01600325.png\"></figure><p>Если растяжение болтов меньше, чем спецификация, ослабьте оба болта и продолжайте следующим образом:</p><p>Затягивать болты, используя те же шаги и значения, за исключением конечного шага для болтов, который был меньше, чем спецификация. Затяните болты.</p><div class=\"callout tip\"><div class=\"callout-head\"><span class=\"callout-ico\">🔧</span>Момент затяжки</div><div class=\"callout-body\"><p>365 Н·м [269 фунт-фут]</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600329.png\" alt=\"01600329.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Если болты, которые были в пределах спецификаций растяжения, затягиваются до максимального значения крутящего момента, отказ болтов может привести к обширному повреждению двигателя.</p></div></div><p>Используйте инструмент для измерения количества растяжек болтов и вычисления, как и ранее.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx6botc.png\" alt=\"cx6botc.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Если болты, которые были стянуты дальше до максимального количества крутящего момента, остаются меньше минимальной спецификации растяжения, шатун и болты ** должны быть заменены.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600330.png\" alt=\"01600330.png\"></figure><h4>Проверка по бокам</h4><ul><li>Чтобы измерить количество соединительного бокового зазора стержня, переместите стержни так далеко, как они будут идти к коленчатой валу. Измерьте боковой зазор с помощью калибра.</li><li><a class=\"lnk doc\" href=\"#/doc/28-001-054-tr\">См. процедуру 001-054 в разделе 1.</a></li></ul><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Оба стержня <b> должны </b> свободно перемещаться из стороны в сторону.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx600da.png\" alt=\"cx600da.png\"></figure><h3>Завершающие операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Этот компонент весит более 23 кг[50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><ul><li>Установите масляную всасывающую трубку и скобки.<a class=\"lnk doc\" href=\"#/doc/28-007-040-tr\">См. процедуру 007-040 в разделе 7.</a></li><li>Установите сборку адаптера моторного масла.<a class=\"lnk doc\" href=\"#/doc/28-007-017\">См. процедуру 007-017 в разделе 7.</a></li><li>Установите новые фильтры полного потока.<a class=\"lnk doc\" href=\"#/doc/28-007-013-tr\">См. процедуру 007-013 в разделе 7.</a></li><li>Заполните двигатель чистым моторным маслом 15W-40.<a class=\"lnk doc\" href=\"#/doc/28-007-025-tr\">См. процедуру 007-025 в разделе 7.</a></li><li>Подсоедините аккумуляторные батареи. См. сервисную документацию изготовителя оборудования.</li><li>Запустите двигатель и проверьте на отсутствие утечек.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ck800wa.png\" alt=\"ck800wa.png\"></figure>","28-001-006-tr":"<h3>Общие сведения</h3><p>Верхние подшипники содержат нефтяную дыру. Нижние подшипники не имеют нефтяной дыры. Оба подшипника обозначены на задней панели с указанием местоположения (верхний или нижний) и размера (стандартный [STD] или сверхразмерный [OS]). Количество подшипника негабаритного указывается в дюймах.</p><p>Используйте подшипник того же размера; стандартный, 0,254 мм [0,010 в], 0,508 мм [0,020 в], или 0,762 мм [0,030 в], который был удален.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600076.png\" alt=\"01600076.png\"></figure><p>Кранкшафт будет проштампован на конце противовеса номер один, чтобы указать, был ли он меньше по размеру. Количество материала, удаленного из основных журналов и журналов стержневых журналов, проштамповываются в этом месте. Размер подшипника крючковатого вала проштампован на противовесе коленчатого вала, прилегающем к месту тяги.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ck800ga.png\" alt=\"ck800ga.png\"></figure><h3>Подготовительные операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>По заключению ряда государственных органов отработанное моторное масло может обладать канцерогенным действием и вредить репродуктивной функции. Не вдыхайте пары, не допускайте попадания внутрь и длительного контакта с отработанным моторным маслом. Если деталь не используется повторно, утилизируйте её по местным природоохранным требованиям.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Чтобы снизить риск травмы, не допускайте попадания горячего масла на кожу.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Масса этого узла больше 23 кг [50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><ul><li>Отсоедините аккумуляторные батареи. Ссылка на оригинальную информацию об услугах производителя оборудования.</li><li>Слить моторное масло. См. процедуру 007-037 в разделе 7.</li><li>Снимите смазочный маслосборник.<a class=\"lnk doc\" href=\"#/doc/28-007-025-tr\">См. процедуру 007-025 в разделе 7.</a></li><li>Удалите фильтры моторного масла.<a class=\"lnk doc\" href=\"#/doc/28-007-013-tr\">См. процедуру 007-013 в разделе 7.</a></li><li>Снять сборку адаптера моторного масла.<a class=\"lnk doc\" href=\"#/doc/28-007-027-tr\">См. процедуру 007-027 в разделе 7.</a></li><li>Удалите масляную всасывающую трубку и скобки. См. процедуру 007-035 в разделе 7.</li><li>Удалите насос моторного масла.<a class=\"lnk doc\" href=\"#/doc/28-007-031-tr\">См. процедуру 007-031 в разделе 7.</a></li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ck800wa.png\" alt=\"ck800wa.png\"></figure><h3>Снятие</h3><p>Убедитесь, что все основные колпачки подшипников определены правильно.</p><p>Блок цилиндра имеет номер, который используется для удержания блока и основных подшипников вместе. Номер проштампован на нижней (стеклоподъемник) части блока в левобережной задней части двигателя.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>В качестве примера используется «709N» <b>только </b>.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Основные подшипники K38 и QSK38 показаны на этой иллюстрации. Основные подшипники K50 и QSK50 пронумерованы от 1 до 9.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6caga.png\" alt=\"mb6caga.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Личная травма и повреждение коленчатого вала могут возникнуть, если коленчатый вал будет сброшен.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Доступ к некоторым боковым болтам предполагает удаление других компонентов.</p></div></div><p>Для каждой основной подшипниковой шапки имеется два боковых болта.</p><p>Удалите основные подшипники по одному за раз.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6csha.png\" alt=\"mb6csha.png\"></figure><p>Каждый основной подшипник содержит тот же номер, который проштампован на блоке. Номер расположения шапки находится на шапке в двух местах.</p><p>Если крышка <b> не</b> отмечена для определения местоположения, настоятельно рекомендуется, чтобы она была отмечена перед удалением из блока цилиндров, чтобы помочь идентифицировать.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6cagb.png\" alt=\"mb6cagb.png\"></figure><p>Удалите основные крепежные болты с подшипником.</p><p>Снимите крышку, используйте главный подшипник, номер детали 4919357.</p><p>Выровнять главный подшипниковый колпачок с основным подшипниковым колпачком.</p><p>Установите крепление на левую и правую масляные рельсы блока двигателя.</p><p>Установите на главный подшипник зажимную пластину съёмника и затяните ручку зажима.</p><p>Поверните регулирующий гайку в верхней части крепления гаечным ключом, чтобы поднять основную подшипниковую шапку.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Если корпус маховика все еще на месте, задняя основная подшипниковая крышка должна быть слегка наклонена вперед для доступа к инструменту. Используйте прыжок или большую отвертку, чтобы наклонить колпачок вперед.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/22800640.png\" alt=\"22800640.png\"></figure><p>Снимите подшипник с крышки и отметьте местоположение в танге для будущей идентификации или анализа.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb800ma.png\" alt=\"mb800ma.png\"></figure><p>Для удаления верхних оболочек подшипников используйте главный подшипниковый уборщик, номер детали 3823818.</p><p>Вращайте коленчатый вал так, чтобы сначала из блока выкатился тан (1) основной несущей оболочки.</p><p>Используйте заграждающее устройство для медленного вращения коленчатого вала. Продолжайте вращать коленчатый вал до тех пор, пока несущая оболочка не выйдет из блока двигателя. Если корпус маховика был снят, коленчатый вал можно повернуть с помощью крепежных болтов коленчатого вала.</p><p>Отметьте верхнее основное место подшипника в зоне касания подшипника.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600626.png\" alt=\"01600626.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Если замена подшипника была инициирована из-за повреждения, проверьте масляную поддон для мусора. Если присутствует значительный мусор, удалите и разберите насос моторного масла и проверьте втулку на предмет повреждения мусора.<a class=\"lnk doc\" href=\"#/doc/28-007-031-tr\">См. процедуру 007-031 в разделе 7.</a></p></div></div><p>Очистите журнал коленчатого вала без винта.</p><p>Проверить журнал на предмет повреждений.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600324.png\" alt=\"01600324.png\"></figure><h3>Очистка и проверка при повторном использовании</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При использовании растворителей, кислот или щелочных материалов для очистки следуйте рекомендациям производителя по применению. Носите очки и защитную одежду, чтобы избежать травм.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При работе со сжатым воздухом применяйте защиту глаз и лица. Разлетающиеся частицы и грязь могут привести к травме.</p></div></div><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не используйте скребок или проволочную щетку, это может повредить подшипники.</p></div></div><p>Убедитесь, что подшипники обозначены для местоположения. Подшипник ** должен быть установлен в его первоначальном месте, если он должен быть использован снова.</p><p>Используйте растворитель для очистки подшипников.</p><p>Просушите сжатым воздухом.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb8bega.png\" alt=\"mb8bega.png\"></figure><p>Осмотрите основные подшипники, болты и шайбы на предмет следующих повреждений:</p><ul><li>Питтинг</li><li>треск</li><li>Повреждение струны.</li></ul><p>Замените поврежденную часть.</p><p>Осмотрите головку каждого болта, чтобы подсчитать количество ударных знаков. Любые болты с пятью ударными знаками на голове ** должны быть заменены.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01a00023.png\" alt=\"01a00023.png\"></figure><p>Проверить подшипники на предмет повреждения.</p><p>Заменить любые подшипники, которые имеют следующие повреждения:</p><ul><li>Никс</li><li>Трещины</li><li>Бёрлз</li><li>Схватки (достаточно глубокие, чтобы их можно было почувствовать ногтем)</li><li>обрывки</li><li>Гугз</li><li>Встроенные частицы</li><li>фреттинг</li><li>Питтинг</li><li>хлопанье</li><li>Коррозия</li><li>Повреждение от замкового танга.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx2besa.png\" alt=\"cx2besa.png\"></figure><p>Нормальный износ подшипника производит гладкую отделку, которая будет носиться в медную подкладку. Обнаруженная медь <b> не всегда </b> указывает на изношенные подшипники. Ссылка на Руководство по повторному использованию частей, Вестник 3810303.</p><p>Если в подшипниках видны большие участки медной обшивки до того, как двигатель накопит 3000 часов, проверьте двигатель на предмет загрязнения мелкими частицами грязи и исправьте проблему.</p><p>Для получения более подробной информации о повреждении подшипника см. Руководство по анализу и предотвращению недержания, Вестник 3810387.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cx8beba.png\" alt=\"cx8beba.png\"></figure><p>Используйте шаровой микрометр. Измерьте толщину подшипника в месте износа. Подшипник <b> должен быть заменен, если он </b> не** в пределах спецификаций.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Стандартная толщина или размер (OS)</th><th></th><th></th><th></th></tr></thead><tbody><tr><td></td><td>мм</td><td></td><td>в</td></tr><tr><td>Стандартный стандарт</td><td>4.280</td><td>Мин</td><td>0.1685</td></tr><tr><td></td><td>4.336</td><td>Макс</td><td>0.1707</td></tr><tr><td>0,010 (OS)</td><td>4.407</td><td>Мин</td><td>0.1735</td></tr><tr><td></td><td>4.463</td><td>Макс</td><td>0.1757</td></tr><tr><td>0,020 (OS)</td><td>4.534</td><td>Мин</td><td>0.1785</td></tr><tr><td></td><td>4.590</td><td>Макс</td><td>0.1807</td></tr><tr><td>0,030 (OS)</td><td>4.661</td><td>Мин</td><td>0.1835</td></tr><tr><td></td><td>4.717</td><td>Макс</td><td>0.1857</td></tr><tr><td>0.040 (OS)</td><td>4.788</td><td>Мин</td><td>0.1885</td></tr><tr><td></td><td>4.844</td><td>Макс</td><td>0.1907</td></tr></tbody></table></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb8betb.png\" alt=\"mb8betb.png\"></figure><h3>Установка</h3><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Номера расположения основных подшипников начинаются с номера 1 в передней части блока цилиндров.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Подшипники K38 пронумерованы от 1 до 7.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Подшипники K50 пронумерованы от 1 до 9.</p></div></div><p>Основные подшипники имеют две ширины. Узкие подшипники соответствуют местам № 1 и № 7 в блоке K38, а также № 1 и № 9 в блоке K50 и QSK50. Широкие подшипники подходят к остальным местам в обоих блоках.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6bega.png\" alt=\"mb6bega.png\"></figure><p>Верхние подшипники содержат нефтяную дыру. Нижние подшипники делают <b>не</b>. Оба подшипника помечены на спине, чтобы указать местоположение и либо стандартный (STD), либо негабаритный (OS). Количество ОС штамповывается на спине в дюймах.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6begb.png\" alt=\"mb6begb.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Предотвратить смешивание грязи с смазкой. Грязная смазка может вызвать сбои в низком пробеге.</p></div></div><p>Используйте безмятежную ткань. Очистите подшипник и монтажную поверхность.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Не смазывайте заднюю часть подшипника.</p></div></div><p>Выровнять зацепление в подшипнике с помощью щели в блоке. Установите подшипники. Конец подшипника ** должен быть ровным с монтажной поверхностью для основной подшипниковой шапки.</p><p>Используйте моторное масло, если двигатель будет работать немедленно. Используйте LubriplateTM 105, или эквивалент, если двигатель будет работать <b>не</b>. Смазать подшипники.</p><p>Повторно используемые подшипники <b>mus</b>t устанавливаются в их первоначальном месте.</p><p>Установите верхние основные подшипники раковин. Используйте тот же метод, который использовался для удаления снарядов. Найдите инструмент для выкатывания на танговом конце подшипника.</p><p>Подшипник танго <b> должен</b> вписаться в щель в седле подшипника, чтобы обеспечить подшипник в правильном месте.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600156.png\" alt=\"01600156.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Только новые двигатели K38 и K50 имеют дюжеточное кольцо (1), которое выступает из основной подшипниковой шапки. Не устанавливайте колпачок с дюбелем в блоке, который не имеет кольцевого дюбеля на других колпачках. Если вы не уверены, попробуйте поместить дюбельное кольцо в правильное отверстие болтов в блоке. Если требуется сила, не устанавливайте кольцевой дол.</p></div></div><p>Если требуется, установите кольцо.</p><p>Используйте ткань без ворса для очистки нижних подшипников и монтажных поверхностей колпачка.</p><p>Выровнять зацепление в подшипнике с помощью щели в основной подшипниковой шапке. Конец подшипника <b> должен быть</b> даже с монтажной поверхностью основной подшипниковой шапки.</p><p>Используйте ту же смазку, которая была нанесена на верхние основные подшипники. Смазать нижние подшипники.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p><b>не</b>* смазывать спинки основных подшипников.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6caaa.png\" alt=\"mb6caaa.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Разрешить избыток масла капать из болтов перед установкой в блок. Избыток масла может вызвать гидравлическое давление, что приводит к повреждению блока цилиндров.</p></div></div><p>Используйте чистое моторное масло для смазки головок болтов, резьбы и шайб.</p><p>Установите шайбы и болты в основной подшипниковой колпачке.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6caaa.png\" alt=\"mb6caaa.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не вращайте коленчатый вал, пока крышки не будут вытянуты к блоку. Повреждение может возникнуть, если подшипники перемещаются из местоположения.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Убедитесь, что сторона крышки и подшипника с подшипником, расположенным на танге, находится к тангу в блоке.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Держите крышку прямо, перемещая ее через отверстия для боковых болтов. Между частями нет или почти нет зазора.</p></div></div><p>Установите главный подшипник.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6caha.png\" alt=\"mb6caha.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Установите болты вручную.</p></div></div><p>Поверните болты, пока они не коснутся шайбы или основной подшипниковой шапки.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6cahb.png\" alt=\"mb6cahb.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>** Не использовать ударные гаечные ключи. Основные несущие оболочки могут выпадать.</p></div></div><p>Используйте оба болта, чтобы вытащить главный несущий колпачок в положение.</p><p>Используйте два гаечных ключа. Затягивайте оба болта одновременно.</p><p>Убедитесь, что крышка касается блока. Если это <b>не </b>, проверьте наличие подшипника вне места.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6cahc.png\" alt=\"mb6cahc.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Сбоку нижней опоры подшипника тяги, которая обрабатывается <b>, должна быть</b> по направлению к основной крышке подшипника.</p></div></div><p>Установите нижнюю опору подшипника тяги коленчатого вала, шайбы замка и болты.<a class=\"lnk doc\" href=\"#/doc/28-001-007-tr\">См. процедуру 001-007 в разделе 1.</a>См. процедуру 001-007 в разделе 1.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6hshb.png\" alt=\"mb6hshb.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не вращайте коленчатый вал до тех пор, пока основные несущие колпачки не будут притянуты к блоку. Повреждение будет иметь место, если подшипники будут перемещаться из местоположения.</p></div></div><p>Поверните коленчатый вал с помощью запирающего инструмента. Если он поворачивается <b>не</b>, уберите основные колпачки подшипника по одному за раз, пока коленчатый вал не повернется свободно. Это помогает найти крышку или подшипник, который <b> не </b> в выравнивании.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shda.png\" alt=\"ks6shda.png\"></figure><p>Используйте чистое моторное масло для смазки головок болтов, резьбы и закаленных простых шайб.</p><p>Установите шайбы и болты для боковой части основной подшипниковой шапки. Для каждой крышки требуется две шайбы и болты.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6csha.png\" alt=\"mb6csha.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Ссылка на последовательность крутящего момента относится к методу прямого крутящего момента <b>только </b>.</p></div></div><p>Для двигателей K38 и QSK38 используйте следующие шаги для затягивания болтов в показанной последовательности.</p><p>Момент затяжки:</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6booc.png\" alt=\"mb6booc.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Ссылка на последовательность крутящего момента относится к методу прямого крутящего момента <b>только </b>.</p></div></div><p>Для двигателей K50 и QSK50 используйте следующие шаги для затягивания болтов в показанной последовательности.</p><p>Момент затяжки:</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6booe.png\" alt=\"mb6booe.png\"></figure><p>Поверните коленчатый вал руками. Если он <b>не</b> повернется, ослабьте основные колпачки подшипников по одному за раз, пока коленчатый вал не повернется свободно. Это помогает найти крышку, которая <b> не </b> в выравнивании.</p><p>Проверьте, чтобы убедиться, что есть конечный допуск.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shda.png\" alt=\"ks6shda.png\"></figure><p>Использовались три различных конструкции болтов.</p><ol><li>12-точечные болты, которые являются черными</li><li>6-точечные болты, которые светло-серые</li><li>6-точечные болты с маркировкой по углу (Часть Номер)<a class=\"lnk part\" href=\"#/part/3628452\">3628452</a>).</li></ol><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>болты (1 и 2) используют процедуру крутящего момента для затягивания. Они могут быть перемешаны и установлены в одном и том же колпачке. болты (3) используют процедуру поворота крутящего момента для затягивания.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Все двигатели, построенные с использованием процедуры поворота крутящего момента, должны иметь процедуру поворота крутящего момента, применяемую при перестроении или ремонте в полевых условиях. Эти двигатели могут быть идентифицированы по маркировке болтов. Старые двигатели, если линия блока не скучает, сохраняют старые значения крутящего момента. В случаях, когда процедура поворота крутящего момента ** невозможна, из-за ограниченного доступа вместо процедуры поворота крутящего момента может использоваться момент затяжки 814 Н•м [600 футов-lb].</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Поскольку крутящий момент, необходимый для процедуры поворота крутящего момента, значительно выше, чем процедура только крутящего момента, Cummins Inc. Рекомендуется использовать множитель крутящего момента и решетку выключателя при продвижении болтов на конечные 90 градусов. Стандартный гаечный ключ с минимальной способностью 407 Н•м [300 фунт-фут], должен использоваться (без крутящего момента множителя) для получения начального значения крутящего момента 339 Н•м [250 фунт-фут].</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6csxa.png\" alt=\"mb6csxa.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Последовательность крутящего момента ниже предназначена для метода крутящего момента плюс угол.</p></div></div><p>Для двигателей K38 и QSK38, затягивайте основные крепежные болты с подшипником поочередно и равномерно, используйте показанную последовательность крутящего момента.</p><p>Момент затяжки:</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6booc.png\" alt=\"mb6booc.png\"></figure><p>Для двигателей К50 и QSK50 затягивайте основные крепежные болты с подшипником попеременно и равномерно. Используйте показанную последовательность крутящего момента.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6booe.png\" alt=\"mb6booe.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Последовательность крутящего момента ниже предназначена для метода крутящего момента плюс угол.</p></div></div><p>Используйте карандаш или писец и пометьте три знака на основных подшипниковых колпачках, прилегающих к трем знакам на головке болтов, как показано. Используйте DykemTM на поверхности крышки, если это необходимо, чтобы сделать отметки видимыми.</p><p>Момент затяжки:</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6csva.png\" alt=\"mb6csva.png\"></figure><p>Установите розетку на болты и выпишите линию на розетке, в соответствии с одной линией на блоке цилиндра. Используйте DykemTM на розетке для ясности. Эта розетка плотно прилегает к головке болтов. Использование изношенной розетки снизит точность.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600296.png\" alt=\"01600296.png\"></figure><p>Альтернативный способ маркировки блока цилиндров состоит в том, чтобы на розетке прописать две линии на 90 градусов друг от друга. Шаблон должен использоваться для точности. Поместите розетку над болтами и переведите одну линию на блок цилиндров. Продвигайте болты на 90 градусов. Вторая линия на розетке должна выровняться с линией на блоке после завершения процедуры поворота крутящего момента.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6tona.png\" alt=\"mb6tona.png\"></figure><p>Разъем поверх болтов поместите с отметкой в соответствии с единственной отметкой на подшипниковой крышке.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600297.png\" alt=\"01600297.png\"></figure><p>Установите 7/16-дюймовые болты длиной около 6 дюймов в соответствующее отверстие для крепления болтов масляного поддона, чтобы предотвратить поворот множителя крутящего момента при наложении крутящего момента на основные несущие болты.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6csnf.png\" alt=\"mb6csnf.png\"></figure><p>Используйте множитель крутящего момента, как показано, чтобы затянуть болты до тех пор, пока линия на розетке не окажется на полпути между двумя отметками на главной подшипниковой крышке.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6csng.png\" alt=\"mb6csng.png\"></figure><p>Показано правильное окончательное местоположение для маркировки головки болтов относительно маркировки колпачка.</p><p>Повторите процедуру для оставшихся болтов. Используйте правильную последовательность крутящего момента.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6csne.png\" alt=\"mb6csne.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>На этой иллюстрации изображены K38 и QSK38. K50 и QSK50 используют одну и ту же последовательность, но пронумерованы от 1 до 18.</p></div></div><p>Используйте следующие шаги для ручного затягивания боковых болтов в показанной последовательности.</p><p>Момент затяжки:</p><div class=\"fig-missing\">Иллюстрация <code>mb6bood.png</code> не выгружена — <a href=\"https://quickserve.cummins.com/rtgraphics/english/service/mb/6/mb6bood.png\" target=\"_blank\" rel=\"noopener\">открыть на QuickServe ↗</a></div><p>Проверьте зазор конца коленчатого вала.<a class=\"lnk doc\" href=\"#/doc/28-001-007-tr\">См. процедуру 001-007 в разделе 1.</a></p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shja.png\" alt=\"ks6shja.png\"></figure><h3>Завершающие операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Масса этого узла больше 23 кг [50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><ul><li>Установите насос моторного масла.<a class=\"lnk doc\" href=\"#/doc/28-007-031-tr\">См. процедуру 007-031 в разделе 7.</a></li><li>Установите масляную всасывающую трубку и скобки. См. процедуру 007-035 в разделе 7.</li><li>Установите смазочный маслосборник.<a class=\"lnk doc\" href=\"#/doc/28-007-025-tr\">См. процедуру 007-025 в разделе 7.</a></li><li>Установите сборку адаптера моторного масла.<a class=\"lnk doc\" href=\"#/doc/28-007-027-tr\">См. процедуру 007-027 в разделе 7.</a></li><li>Установите новые фильтры моторного масла.<a class=\"lnk doc\" href=\"#/doc/28-007-013-tr\">См. процедуру 007-013 в разделе 7.</a></li><li>Заполните двигатель моторным маслом. См. процедуру 007-037 в разделе 7.</li><li>Подсоедините аккумуляторные батареи. Ссылка на оригинальную информацию об услугах производителя оборудования.</li><li>Запустите двигатель и проверьте на отсутствие утечек.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ck800wa.png\" alt=\"ck800wa.png\"></figure>","28-001-007-tr":"<h3>Подготовительные операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Масса этого узла больше 23 кг [50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><ul><li>Отсоедините аккумуляторные батареи. См. сервисное руководство изготовителя машины.</li><li>Слить моторное масло.<a class=\"lnk doc\" href=\"#/doc/28-007-025-tr\">См. процедуру 007-025 в разделе.</a></li><li>Удалите масляные фильтры.<a class=\"lnk doc\" href=\"#/doc/28-007-013-tr\">См. процедуру 007-013 в разделе 7.</a></li><li>Удалите сборку адаптера масляного поддон с блочного фланца.<a class=\"lnk doc\" href=\"#/doc/28-007-027-tr\">См. процедуру 007-027 в разделе 7.</a></li><li>Удалите все масляные передающие и всасывающие трубки и скобки. См. процедуру 007-035 в разделе 7.</li><li>Удалите все масляные передающие и всасывающие трубки и скобки. См. процедуру 001-061 в разделе 1.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ck800wa.png\" alt=\"ck800wa.png\"></figure><h3>Снятие</h3><p>Удалите два болта из подшипника подшипника нижней тяги и удалите подпорный держатель.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6hshb.png\" alt=\"mb6hshb.png\"></figure><p>Чтобы удалить полости подшипника тяги, держите коленчатый вал на одном конце его тяги и вращайте его с помощью заграждения. Если **только одна из несущих половин вращается, переместите коленчатый вал на другой конец его тяги и снова поверните коленчатый вал.</p><p>Отметьте расположение каждого подшипника тяги, передней и задней, на стороне, противоположной той, которая обращена к фланцу коленчатого вала.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600298.png\" alt=\"01600298.png\"></figure><p>Осмотрите лица на фланце тяги коленчатого вала и поверхности тяги подшипниковых половин. Подшипники для толчков доступны в стандартном исполнении и имеют следующие размеры:</p><ul><li>0,254 мм [0,010 в]</li><li>0,508 мм [0,020 in]</li><li>0,762 мм [0,030 в]</li><li>1,016 мм [0,040 in]</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600299.png\" alt=\"01600299.png\"></figure><h3>Проверка при повторном использовании</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При очистке растворителями, кислотами и щелочными составами соблюдайте указания их изготовителя. Работайте в защитных очках и защитной одежде, чтобы снизить риск травмы.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При работе со сжатым воздухом применяйте защиту глаз и лица. Разлетающиеся частицы и грязь могут привести к травме.</p></div></div><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не используйте скребок или проволочную щетку. Это может привести к повреждению подшипников.</p></div></div><p>Используйте растворитель для очистки подшипников.</p><p>Просушите сжатым воздухом.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb8bega.png\" alt=\"mb8bega.png\"></figure><p>Используйте микрометр для измерения толщины подшипника тяги в месте износа. Свет указывает, где коленчатый вал соприкоснулся с подшипником.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Стандартная толщина или размер</th><th></th><th></th><th></th></tr></thead><tbody><tr><td></td><td>мм</td><td></td><td>в</td></tr><tr><td>Стандартный стандарт</td><td>4.826</td><td>Мин</td><td>0.1900</td></tr><tr><td></td><td>4.940</td><td>Макс</td><td>0.1945</td></tr><tr><td>Размер 0,254 мм [0,010 в]</td><td>5.080</td><td>Мин</td><td>0.2000</td></tr><tr><td></td><td>5.194</td><td>Макс</td><td>0.2045</td></tr><tr><td>Размер 0,508 мм [0,020 в]</td><td>5.334</td><td>Мин</td><td>0.2100</td></tr><tr><td></td><td>5.448</td><td>Макс</td><td>0.2145</td></tr><tr><td>Размер 0,762 мм [0,030 в]</td><td>5.588</td><td>Мин</td><td>0.2200</td></tr><tr><td></td><td>5.702</td><td>Макс</td><td>0.2245</td></tr><tr><td>Размер 1,016 мм [0,040 в]</td><td>5.842</td><td>Мин</td><td>0.2300</td></tr><tr><td></td><td>5.956</td><td>Макс</td><td>0.2345</td></tr></tbody></table></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb8betb.png\" alt=\"mb8betb.png\"></figure><h3>Установка</h3><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Канавки в подшипниках тяги <b> должны</b> обращены к фланцу на коленчатом валу.</p></div></div><p>Смазать два подшипника тяги чистым моторным маслом и вставить их в опору подшипника тяги.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Переместить коленчатый вал в переднюю или заднюю часть, если это необходимо для установки второго подшипника тяги.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600301.png\" alt=\"01600301.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Обрабатываемая сторона подшипника подшипника нижней тяги <b> должна</b> быть по направлению к основной подшипниковой шапке.</p></div></div><p>Установите удерживающий элемент подшипника тяги, стиральную машину и болты.</p><div class=\"callout tip\"><div class=\"callout-head\"><span class=\"callout-ico\">🔧</span>Момент затяжки</div><div class=\"callout-body\"><p>40 Н·м [30 фунт-фут]</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6hshb.png\" alt=\"mb6hshb.png\"></figure><p>Используйте индикатор циферблата для измерения конечного зазора. Переместите коленчатый вал на один конец его тяги и обнулите циферблат. Переместите коленчатый вал на другой конец его тяги и возьмите чтение.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Кранкшафт Конец зазора</th><th></th><th></th></tr></thead><tbody><tr><td>мм</td><td></td><td>в</td></tr><tr><td>0.13</td><td>Мин</td><td>0.005</td></tr><tr><td>0.51</td><td>Макс</td><td>0.020</td></tr></tbody></table></div><p>Если зазор <b> не</b> в пределах спецификаций, проверьте наличие постороннего материала на подшипниках тяги или фланце коленчатого вала. Для регулировки зазора на конце имеются подшипники с большой тягой.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shja.png\" alt=\"ks6shja.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Рекомендуется повторно проверить конечный зазор коленчатого вала после установки двигателя в приложение.</p></div></div><p>Отпустите напряжение на ремне привода охлаждающего вентилятора, если он установлен.<a class=\"lnk doc\" href=\"#/doc/28-008-002-tr\">См. процедуру 008-002 в разделе 8.</a></p><p>Удалите доступную крышку ручного отверстия. См. процедуру 001-035 в разделе 1.</p><p>Используйте заграждающее устройство для вращения двигателя так, чтобы шатун журнал был напротив отверстия крышки ручного отверстия. Если шатуны уже находятся в этом положении, когда крышка ручного отверстия удалена, используйте заградительное устройство для вращения коленчатого вала немного в противоположном направлении к нормальному вращению. Это освобождает погрузку на зубчатый состав.</p><p>Прикрепите циферблатный индикатор, опираясь на вибрационный демпфер.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks400dc.png\" alt=\"ks400dc.png\"></figure><p>Используйте pry bar или аналогичный, чтобы переместить коленчатый вал назад, попробовав против коленчатого вала паутину.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p><b>не</b> попробуй против шатунов или противовесов коленчатого вала.</p></div></div><p>Установите индикатор циферблата до нуля.</p><p>Переместите коленчатый вал в противоположном направлении, поищая в сети коленчатого вала.</p><p>Проверьте показания на индикаторе циферблата, чтобы подтвердить, что коленчатый вал имеет конечный зазор, который находится в пределах, показанных выше.</p><p>Если ранее ослабли, нажмите охлаждающий ремень привода вентилятора.<a class=\"lnk doc\" href=\"#/doc/28-008-002-tr\">См. процедуру 008-002 в разделе 8.</a></p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01s00036.png\" alt=\"01s00036.png\"></figure><h3>Завершающие операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Этот компонент весит более 23 кг[50 фунтов]. Чтобы не получить тяжёлую травму, поднимайте этот узел с помощником или подходящим грузоподъёмным оборудованием.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><ul><li>Установите масляные передающие и всасывающие трубки и скобки. См. процедуру 007-035 в разделе 7.</li><li>Установите масляные передающие и всасывающие трубки и скобки. См. процедуру 001-061 в разделе 1.</li><li>Установите сборку адаптера масляного поддон на блочный фланж с помощью новой прокладки.<a class=\"lnk doc\" href=\"#/doc/28-007-027-tr\">См. процедуру 007-027 в разделе 7.</a></li><li>Установите новые масляные фильтры.<a class=\"lnk doc\" href=\"#/doc/28-007-013-tr\">См. процедуру 007-013 в разделе 7.</a></li><li>Заполните двигатель чистым моторным маслом 15W-40.<a class=\"lnk doc\" href=\"#/doc/28-007-025-tr\">См. процедуру 007-025 в разделе 7.</a></li><li>Подсоедините аккумуляторные батареи. См. сервисное руководство изготовителя машины.</li><li>Запустите двигатель и проверьте на отсутствие утечек.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ck800wa.png\" alt=\"ck800wa.png\"></figure>","28-001-010-tr":"<h3>Снятие</h3><p>Двигатели K38 и K50 содержат два втулки распределительного вала в каждом цилиндровом отверстии, за исключением отверстий в левом береге (LB) передней и правой берег (RB) задней части. Передняя и задняя части LB содержат один автобус <b>только </b>.</p><p>Когда двигатели изготовлены, втулка, номер детали<a class=\"lnk part\" href=\"#/part/3175805\">3175805</a>, который не содержит <b>не</b> внутренней масляной канавки, установлен во всех отверстиях, кроме передней и задней частей LB. Для уменьшения путаницы в полевых условиях для обслуживания доступен только втулка, номер детали 205230, с внутренней масляной канавкой.</p><p>Если втулка в цилиндрическом отверстии, содержащем два втулки <b>, должна быть заменена, то оба втулки </b>* должны быть заменены. Рекомендуется, чтобы в случае замены одного втулки банка двигателя*** все втулки для этого банка были заменены.</p><p>Используйте сборку водителя втулки распределительного вала, Номер детали 3376637 и комплект водителя, Номер детали 3376634.</p><p>Для удобства удаления/установки доступны гидравлические кустарники. Они включают в себя гидравлический приводной комплект, Часть Номер 3823621, комплект установки / удаления, Часть Номер 3823647 и центрирующий направляющий комплект, Часть Номер 3823653.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ka3bswa.png\" alt=\"ka3bswa.png\"></figure><p>Используйте комплект водителя (1). Удалите втулку (2) распределительного вала из цилиндрового отверстия, содержащего один втул.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cg6bsma.png\" alt=\"cg6bsma.png\"></figure><p>Используйте комплект водителя (1). Нажмите на одну из втулок (2), пока она не коснется другой. Выталкивайте оба втулки (2) одновременно.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cg6bsmb.png\" alt=\"cg6bsmb.png\"></figure><h3>Очистка и проверка при повторном использовании</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При очистке растворителями, кислотами и щелочными составами соблюдайте указания их изготовителя. Работайте в защитных очках и защитной одежде, чтобы снизить риск травмы.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При работе со сжатым воздухом применяйте защиту глаз и лица. Летающий мусор и грязь могут нанести телесные повреждения.</p></div></div><p>Используйте салфетку. Удалите любые заусенцы и острые края из цилиндрового отверстия.</p><p>Используйте растворитель для очистки цилиндра.</p><p>Просушите сжатым воздухом.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cg6brta.png\" alt=\"cg6brta.png\"></figure><p>Измерьте внутренний диаметр.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Цилиндр Camshaft Bushing в блоке</th><th></th><th></th></tr></thead><tbody><tr><td>мм</td><td></td><td>в</td></tr><tr><td>80.949</td><td>Мин</td><td>3.1869</td></tr><tr><td>81.013</td><td>Макс</td><td>3.1894</td></tr></tbody></table></div><p>Если внутренний диаметр не соответствует спецификациям, отремонтируйте блок, установив ремонтный рукав.</p><p>См. Руководство по альтернативному ремонту, Вестник 3379035.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cg6brta.png\" alt=\"cg6brta.png\"></figure><h3>Установка</h3><p>Для установки первого втулки в отверстия, которые требуют двух втулок:</p><ul><li>Поместите втулку (2) так, чтобы сужение втулки (3) было направлено к поверхности головки цилиндра блока. Удлиненное отверстие (4) должно находиться на стороне цилиндра, которая находится ближе всего к тройке блока.</li><li>Используйте сборку водителя. Проталкивайте втулку через цилиндрический отсек. Втулка ** должна быть ровная или не более 1,6 мм [0,0625 дюйма] ниже поверхности блочной сети (5).</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cg6bsha.png\" alt=\"cg6bsha.png\"></figure><p>Поместите вторую втулку (2) для цилиндра, как описано ранее.</p><ul><li>Используйте сборку водителя. Нажмите на втулку в цилиндре, пока она не будет ровным с или не более 1,6 мм [0,0625 дюйма ] ниже поверхности блочной паутины (5).</li><li>Убедитесь, что нефтяная скважина (6) открыта и чиста.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/cg6bshb.png\" alt=\"cg6bshb.png\"></figure><p>Для установки единичных втулок на передней и задней части LB:</p><ul><li>Поместите втулку (2) так, чтобы вытянутое отверстие в втулке (4) соответствовало нефтяному отверстию в блоке (6). Масляные отверстия в втулке будут ближе всего к блоку цилиндров. Сцепной сустав (3) будет направлен в сторону борта цилиндра.</li><li>Используйте сборку водителя. Нажмите на втулку в цилиндре, пока она не будет ровным с или не более 1,6 мм [0,0625 дюйма ] ниже поверхности блочной паутины (5).</li><li>Проверьте, чтобы убедиться, что нефтяная дыра в блоке (6) выровнена с вытянутым отверстием в втулке (4).</li><li>Убедитесь, что нефтяная скважина (6) открыта и чиста.</li></ul><div class=\"fig-missing\">Иллюстрация <code>cg6bshc.png</code> не выгружена — <a href=\"https://quickserve.cummins.com/rtgraphics/english/service/cg/6/cg6bshc.png\" target=\"_blank\" rel=\"noopener\">открыть на QuickServe ↗</a></div>","28-001-016-tr":"<h3>Подготовительные операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>По заключению ряда государственных органов отработанное моторное масло может обладать канцерогенным действием и вредить репродуктивной функции. Не вдыхайте пары, не допускайте попадания внутрь и длительного контакта с отработанным моторным маслом. Если деталь не используется повторно, утилизируйте её по местным природоохранным требованиям.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Чтобы снизить риск травмы, не допускайте попадания горячего масла на кожу.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Этот компонент или сборка весит более 23 кг [50 фунтов] или более. Чтобы предотвратить серьезные травмы, обязательно обратитесь за помощью или используйте соответствующее подъемное оборудование, чтобы поднять этот компонент или сборку.</p></div></div><ul><li>Отсоедините аккумуляторные батареи. См. сервисную документацию изготовителя оборудования.</li><li>Отключите подачу воздуха/топлива к воздухозаборнику, если он оборудован.<a class=\"lnk doc\" href=\"#/doc/102-012-022\">См. процедуру 012-022 в разделе 12.</a></li><li>Слить масло. См. процедуру 007-037 в разделе 7.</li><li>Удалите фильтры полного потока.<a class=\"lnk doc\" href=\"#/doc/28-007-013-tr\">См. процедуру 007-013 в разделе 7.</a></li><li>Удалите масляную всасывающую трубку. См. процедуру 007-035 в разделе 7.</li><li>Удалите адаптер масляной подкладки.<a class=\"lnk doc\" href=\"#/doc/28-007-027-tr\">См. процедуру 007-027 в разделе 7.</a></li><li>Удалите двигатель и поместите на подставку двигателя.<a class=\"lnk doc\" href=\"#/doc/28-000-001-tr\">См. процедуру 000-001 в разделе 0.</a></li><li>Удалите флешлейт, если он установлен.<a class=\"lnk doc\" href=\"#/doc/28-016-004-tr\">См. процедуру 016-004 в разделе 16.</a></li><li>Удалите маховик, если он установлен.<a class=\"lnk doc\" href=\"#/doc/28-016-005-tr\">См. процедуру 016-005 в разделе 16.</a></li><li>Снимите кожух маховика.<a class=\"lnk doc\" href=\"#/doc/28-016-006-tr\">См. процедуру 016-006 в разделе 16.</a></li><li>Снимите переднюю крышку передних колес.<a class=\"lnk doc\" href=\"#/doc/28-001-031-tr\">См. процедуру 001-031 в разделе 1.</a></li><li>Снять соединительные штанги с подшипниками.<a class=\"lnk doc\" href=\"#/doc/28-001-054-tr\">См. процедуру 001-054 в разделе 1.</a></li><li>Удалите основные подшипники.<a class=\"lnk doc\" href=\"#/doc/28-001-006-tr\">См. процедуру 001-006 в разделе 1.</a></li><li>Удалите головку цилиндра.<a class=\"lnk doc\" href=\"#/doc/28-002-004-tr\">См. процедуру 002-004 в разделе 2.</a>.</li><li>Удалите поршень и соединительную сборку стержня.<a class=\"lnk doc\" href=\"#/doc/28-001-054-tr\">См. процедуру 001-054 в разделе 1.</a></li></ul><h3>Снятие</h3><p>Удалите два болта. Удалите опору подшипника нижней тяги.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6hshb.png\" alt=\"mb6hshb.png\"></figure><p>Удалить и отметить оба коленчатых вала подшипников.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6behb.png\" alt=\"mb6behb.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Этот компонент или сборка весит более 23 кг [50 фунтов] или более. Чтобы предотвратить серьезные травмы, обязательно обратитесь за помощью или используйте соответствующее подъемное оборудование, чтобы поднять этот компонент или сборку.</p></div></div><p>Используйте нейлоновую стропу и подъемник, чтобы удалить коленчатый вал.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shha.png\" alt=\"ks6shha.png\"></figure><p>Удалите и пометьте верхние основные подшипники. Отметьте местоположение подшипника на танге.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6beha.png\" alt=\"mb6beha.png\"></figure><p>Удалите шесть болтов.</p><p>Удалите опору подшипника коленчатого вала.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/mb6hsha.png\" alt=\"mb6hsha.png\"></figure><h3>Очистка и проверка при повторном использовании</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При очистке растворителями, кислотами и щелочными составами соблюдайте указания их изготовителя. Работайте в защитных очках и защитной одежде, чтобы снизить риск травмы.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При работе со сжатым воздухом применяйте защиту глаз и лица. Разлетающиеся частицы и грязь могут привести к травме.</p></div></div><p>Очистите коленчатый вал с помощью растворителя и высушите сжатым воздухом.</p><p>Проверьте коленчатый вал на наличие никсов или царапин. Если отметка может <b>не</b> ощущаться ногтем, нет никакой ценности в полировании коленчатого вала.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdec.png\" alt=\"ks8bdec.png\"></figure><p>Используйте абразивную подушку Scotch-BriteTM 7448, номер детали 3823258 или эквивалент, чтобы удалить обесцвечивание или легкие царапины с обработанных поверхностей.</p><p>Кранкшафт *** должен быть снова очищен, если выполняется эта полировка.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bded.png\" alt=\"ks8bded.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При очистке растворителями, кислотами и щелочными составами соблюдайте указания их изготовителя. Работайте в защитных очках и защитной одежде, чтобы снизить риск травмы.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При работе со сжатым воздухом применяйте защиту глаз и лица. Разлетающиеся частицы и грязь могут привести к травме.</p></div></div><p>Двигатели K2000E, K1800E и K1500E используют коленчатый вал, имеющий круг затвора диаметром 77,47 мм [3,050 в] в носу. Резьбы катятся, <b>не</b> разрезаются, как на более ранних коленчатых валах К50.</p><p>Чтобы очистить прокатанную резьбу, промыть растворителем. Сушить резьбу сжатым воздухом. Если требуется дополнительная чистка, щетку с нейлоновой щеткой.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks600sa.png\" alt=\"ks600sa.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При очистке растворителями, кислотами и щелочными составами соблюдайте указания их изготовителя. Работайте в защитных очках и защитной одежде, чтобы снизить риск травмы.</p></div></div><p>Используйте растворитель и щетку для очистки всех нефтяных бурений.</p><p>Используйте легкое консервантное масло для смазки детали, чтобы предотвратить ржавчину.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6sheb.png\" alt=\"ks6sheb.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При очистке растворителями, кислотами и щелочными составами соблюдайте указания их изготовителя. Работайте в защитных очках и защитной одежде, чтобы снизить риск травмы.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Новые коленчатые валы покрыты тяжелым консервантом. Используйте растворитель для тщательного удаления покрытия. Чистить или смыть упаковочный мусор с нефтяных буровых установок перед установкой коленчатого вала в двигателе.</p></div></div><p>Используйте отточенный камень для полировки поверхности наружного диаметра в передней и задней местах уплотнения масла, месте установки маховика и месте демпфера вибрации. Удалите все мелкие царапины и канавки.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shea.png\" alt=\"ks6shea.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При очистке растворителями, кислотами и щелочными составами соблюдайте указания их изготовителя. Работайте в защитных очках и защитной одежде, чтобы снизить риск травмы.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При работе со сжатым воздухом применяйте защиту глаз и лица. Разлетающиеся частицы и грязь могут привести к травме.</p></div></div><p>Используйте растворитель для очистки коленчатого вала.</p><p>Просушите сжатым воздухом.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Обязательно выдувайте резьбовые отверстия на каждом конце коленчатого вала и нефтяных буровых скважин. Используйте легкое консервантное масло, чтобы предотвратить ржавчину во время восстановления двигателя. Заклейте дырки на резьбах.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdec.png\" alt=\"ks8bdec.png\"></figure><p>Паутины коленчатого вала пронумерованы спереди коленчатого вала. Номер запечатан в сети.</p><p>К50 коленчатый вал содержит 16 паутины (не показаны).</p><p>Кранчхейт K38 содержит 12 паутин, как показано на рисунке.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks600gb.png\" alt=\"ks600gb.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Если противовесы сняты, они должны быть установлены в правильном положении на том же коленчатом валу. Если они установлены в неправильном положении, может произойти повреждение двигателя.</p></div></div><p>К50 коленчатые валы содержат противовесы, которые закручены болтами. Противовесы имеют такое же количество, как и сеть, к которой они прикреплены. К50 коленчатый вал содержит восемь противовесов.</p><p>Если противовес <b> должен быть заменен, коленчатый вал </b> должен быть снова сбалансирован. См. Руководство по альтернативному ремонту, Вестник 3379035.</p><p>Более новые коленчатые валы содержат кольцевой дюбель для противовесов. Противовесы <b> не </b> взаимозаменяемы между новыми и старыми коленчатыми валами.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks600gc.png\" alt=\"ks600gc.png\"></figure><p>Измерьте внешний диаметр в показанных местах.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Краншафт снаружи диаметра</th><th></th><th></th><th></th></tr></thead><tbody><tr><td></td><td>мм</td><td></td><td>в</td></tr><tr><td>Местонахождение (1)</td><td>110.74</td><td>Мин</td><td>4.360</td></tr><tr><td></td><td>110.77</td><td>Макс</td><td>4.361</td></tr><tr><td>Местонахождение (2)</td><td>111.07</td><td>Мин</td><td>4.373</td></tr><tr><td></td><td>111.13</td><td>Макс</td><td>4.375</td></tr><tr><td>Местонахождение (3)</td><td>184.10</td><td>Мин</td><td>7.248</td></tr><tr><td></td><td>184.15</td><td>Макс</td><td>7.250</td></tr></tbody></table></div><p>Проверьте резьбу на предмет повреждения на обоих концах коленчатого вала.</p><p>При необходимости см. Руководство по альтернативному ремонту, Бюллетень 3379035, для инструкций по ремонту.</p><p>Проверьте ролл-булавки (4) на предмет повреждения. Замените штифты, если они повреждены.</p><p>Штифты для крена ** должны быть установлены, потому что они выравнивают вибрационный демпфер и маховик с коленчатым валом. Вибрационный демпфер и маховик содержат указательные знаки, необходимые для правильной регулировки клапанов и форсунки.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shta.png\" alt=\"ks6shta.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Двигатели K2000E, K1800E и K1500E используют ROLLED резьбу в коленчатом валу носа. Не используйте резающий кран для преследования или очистки резьбы, или может возникнуть повреждение или сбой.</p></div></div><p>Вставки для спасения резьбы <b> не</b> разрешены в носу коленчатого вала.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks600va.png\" alt=\"ks600va.png\"></figure><p>Осмотрите зоны контакта с коленчатым валом на предмет износа. Износ канавки допустим, если она непрерывна и не более 0,12 мм [0,05 дюйма ] в глубину.</p><p>Если глубина износа канавки больше, чем указано выше, коленчатый вал *** должен быть заменен.</p><p>Если глубина износа меньше, чем указано выше, для ремонта поверхности может быть установлен износной рукав. Используйте следующую процедуру для установки уплотнения передней коленчатой валки с износостойким рукавом.<a class=\"lnk doc\" href=\"#/doc/28-001-023-tr\">См. процедуру 001-023 в разделе 1.</a></p><p>Установка ремонтного рукава на нос передней коленчатой вал рекомендуется во время реконструкции для защиты носа коленчатой вал.</p><p>Ремонтный рукав <b> не</b> доступен для носа заднего коленчатого вала, поскольку он уже включен в уплотнение заднего коленчатого вала.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Нос коленчатого вала не должен быть отремонтирован с использованием какого-либо металлического распыления или процесса сварки.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01500035.png\" alt=\"01500035.png\"></figure><p>Проверьте основные журналы подшипников и журналы подшипников стержней на предмет повреждения или чрезмерного износа. Незначительные царапины приемлемы.</p><p>Если ногтей попадает в царапину, коленчатый вал *** должен быть заменен или обработан. См. Руководство по альтернативному ремонту, Вестник 3379035.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shsa.png\" alt=\"ks6shsa.png\"></figure><p>Измерьте внешний диаметр всех журналов и толщину фланца тяги.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Главная страница Журнал Подшипников За пределами Диаметра (6)</th><th></th><th></th><th></th></tr></thead><tbody><tr><td></td><td>мм</td><td></td><td>в</td></tr><tr><td>Стандартный стандарт</td><td>165.05</td><td>Мин</td><td>6.498</td></tr><tr><td>165.10</td><td>Макс</td><td>6.500</td><td></td></tr><tr><td>Недостаток 0,25 мм [0,010 в]</td><td>164.80</td><td>Мин</td><td>6.488</td></tr><tr><td>164.85</td><td>Макс</td><td>6.490</td><td></td></tr><tr><td>Недостаток 0,50 мм [0,020 в]</td><td>164.55</td><td>Мин</td><td>6.478</td></tr><tr><td>164.60</td><td>Макс</td><td>6.480</td><td></td></tr><tr><td>Недостаток 0,76 мм [0,030 в]</td><td>164.29</td><td>Мин</td><td>6.468</td></tr><tr><td>164.34</td><td>Макс</td><td>6.470</td><td></td></tr><tr><td>Недостаток 1,016 мм [0,040 в]</td><td>164.03</td><td>Мин</td><td>6.458</td></tr><tr><td>164.08</td><td>Макс</td><td>6.460</td><td></td></tr></tbody></table></div><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Crankshaft Connecting Rod Journal Outside Diameter (5) (недоступная ссылка)</th><th></th><th></th><th></th></tr></thead><tbody><tr><td></td><td>мм</td><td></td><td>в</td></tr><tr><td>Стандартный стандарт</td><td>107.87</td><td>Мин</td><td>4.247</td></tr><tr><td>107.95</td><td>Макс</td><td>4.250</td><td></td></tr><tr><td>Недостаток 0,25 мм [0,010 в]</td><td>107.62</td><td>Мин</td><td>4.237</td></tr><tr><td>107.70</td><td>Макс</td><td>4.240</td><td></td></tr><tr><td>Недостаток 0,50 мм [0,020 в]</td><td>107.37</td><td>Мин</td><td>4.227</td></tr><tr><td>107.45</td><td>Макс</td><td>4.230</td><td></td></tr><tr><td>Недостаток 0,75 мм [0,030 в]</td><td>107.11</td><td>Мин</td><td>4.217</td></tr><tr><td>107.19</td><td>Макс</td><td>4.220</td><td></td></tr><tr><td>Недостаток 1,016 мм [0,040 в]</td><td>106.85</td><td>Мин</td><td>4.207</td></tr><tr><td>106.93</td><td>Макс</td><td>4.210</td><td></td></tr></tbody></table></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Кранкшафт может быть обработан с меньшим размером, если внешний диаметр <b> не </b> в пределах спецификаций. <b> Всегда</b> перемалывают все журналы, когда один из них <b> не</b> в пределах спецификаций.</p></div></div><p>Доступны подшипники для стержней и основные подшипники. См. Alternative Repair Manual, Bulletin 3379035, for grinding specifications and instructions.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Подшипники с большой тягой доступны, если расстояние тяги <b> не </b> в пределах спецификаций. Доступны подшипники толщиной 0,25 мм [0,010 в], 0,51 мм [0,020 в], 0,76 мм [0,030 в] и 1,02 мм [0,040 в], более толстые, чем стандартные. Если коленчатый вал ** должен быть обработан для подшипника с большой тягой, см. Руководство по альтернативному ремонту, Бюллетень 3379035.</p></div></div><p>Используйте легкое консервантное масло для смазки коленчатого вала, чтобы предотвратить ржавчину. Если коленчатый вал не будет установлен немедленно, используйте масло с тяжелым консервантом.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shtb.png\" alt=\"ks6shtb.png\"></figure><p>Измерьте тяговый фланж.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Фланж Фрост (7)</th><th></th><th></th></tr></thead><tbody><tr><td>мм</td><td></td><td>в</td></tr><tr><td>12.52</td><td>Мин</td><td>0.493</td></tr><tr><td>12.75</td><td>Макс</td><td>0.502</td></tr></tbody></table></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shtb.png\" alt=\"ks6shtb.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Болты должны быть плотными или противовес может упасть, что приведет к серьезным повреждениям двигателя. Любые свободные болты должны быть заменены новыми болтами.</p></div></div><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Болты не могут быть использованы повторно и должны быть заменены новыми болтами.</p></div></div><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Проверьте новые болты на предмет видимых повреждений или износа. Отбросьте болты, если есть какие-либо видимые повреждения или износ резьбы, шеи или головки болтов.</p></div></div><p>Используйте гаечный ключ для проверки крутящего момента противовесных болтов. Каждый противовес содержит два болта.</p><div class=\"callout tip\"><div class=\"callout-head\"><span class=\"callout-ico\">🔧</span>Момент затяжки</div><div class=\"callout-body\"><p>285 Н·м [210 фунт-фут]</p></div></div><p>Отметьте любые противовесы, которые имеют свободные болты.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6bosa.png\" alt=\"ks6bosa.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Следующий шаг применяется только к противовесам, которые содержат свободные болты.</p></div></div><p>Удалите болты (8) и шайбы (9).</p><p>Удалите противовес.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6boma.png\" alt=\"ks6boma.png\"></figure><p>Проверьте противовес и коленчатый вал на наличие трения или повреждения между спаривающимися поверхностями. Если противовес поврежден, противовес <b> должен быть заменен, а коленчатый вал </b> должен быть сбалансирован. Если коленчатый вал поврежден, коленчатый вал *** должен быть заменен или заменен противовес и коленчатый вал отремонтирован.</p><p>**Не более 0,51 мм [0,020 in] может быть удалено из коленчатого вала монтажной площадки для ремонта фреттинга.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600656.png\" alt=\"01600656.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Если противовес снят, он должен быть установлен с номером детали в направлении ближайшего основного несущего журнала. Если противовес установлен неправильно, вес может ударить по соединительному стержню, нанеся большой ущерб двигателю.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Убедитесь, что противовес возвращен в исходное место. Противовесы имеют такое же количество штампов, как и сеть, к которой они прикреплены.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600658.png\" alt=\"01600658.png\"></figure><p>Там <b> не должно быть</b> помех между коленчатым валом и противовесом и бортами монтажной площадки.</p><p>Смазать шайбы и болты чистым моторным маслом.</p><p>Установите шайбы (9) и болты (8).</p><p>Затяните болты.</p><div class=\"callout tip\"><div class=\"callout-head\"><span class=\"callout-ico\">🔧</span>Момент затяжки</div><div class=\"callout-body\"><p>285 Н·м [210 фунт-фут]</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600655.png\" alt=\"01600655.png\"></figure><p>При затягивании болтов визуально осмотрите противовес на предмет наличия помех в коленке.</p><p>Там <b> не должно быть</b> помех между коленчатым валом и противовесом и бортами монтажной площадки.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600663.png\" alt=\"01600663.png\"></figure><p>Осмотрите спаривающуюся поверхность подшипника тяги на предмет повреждения.</p><p>Используйте салфетки или крокус, если это необходимо, чтобы удалить любые заусенцы или другие дефекты.</p><p>Тщательно очищайте опору и удерживающий элемент подшипника тяги.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01600633.png\" alt=\"01600633.png\"></figure><h3>Магнитный крэк-инспект</h3><p>Используйте машину для тестирования магнитных частиц.</p><p>Выполняйте выстрел головы и метод осмотра. Затем выполните выстрел катушки и метод осмотра.</p><p>Настройка машины на 1800 ампер VDC или исправленный VAC.</p><p>Используйте непрерывный метод. Мокрый <b>только </b> 1/3 коленчатого вала за раз.</p><p>Проверьте коленчатый вал на наличие трещин.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdsa.png\" alt=\"ks8bdsa.png\"></figure><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Амперный виток — это электрический ток одного ампера, протекающий через катушку, умноженный на количество витков в катушке.</p></div></div><p>Используйте метод выстрела катушки. Используйте катушку, которая имеет диаметр не менее 514 мм [20.250 дюймов ].</p><p>Используйте непрерывный метод для нанесения выстрела катушки.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Ампера (Ampere Turns)</th><th></th></tr></thead><tbody><tr><td>Минимум</td><td>4500 VDC или исправленный VAC</td></tr><tr><td>Максимум</td><td>5000 VDC или исправленный VAC</td></tr></tbody></table></div><p>Проверьте коленчатый вал на наличие трещин.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdsb.png\" alt=\"ks8bdsb.png\"></figure><p>Пределы приема - Открытые указания:</p><p>Открытое показание видно глазу после завершения операции смачивания. Указание ниже поверхности <b> не</b> видно глазу после завершения операции смачивания. Указание ниже поверхности можно увидеть с помощью ультрафиолетового света, который является частью машины.</p><p>**не использовать коленчатый вал, если:</p><ul><li>Есть указание в филе или в затененной области</li><li>Есть указание, что проходит через диагональ 45 градусов от нефтяной дыры или уходит в масляную дыру.</li><li>Есть указание, которое длиннее 6 мм [0,250 дюйма]</li><li>На одном журнале имеется более четырех указаний.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdna.png\" alt=\"ks8bdna.png\"></figure><p>Пределы приема - Показания ниже поверхности:</p><p>**не использовать коленчатый вал, если:</p><ul><li>Есть указание в филе или в затененной области, которая находится в окружном направлении.</li><li>Имеется указание в окружном направлении, которое длиннее 25,4 мм [1,00 in].</li><li>Имеется указание в осевом направлении, которое длиннее 9,5 мм [0,375 в].</li><li>Есть указание, что ближе, чем 1,5 мм [0,0625 в] к масляной дыре.</li><li>Есть указание, что проходит через диагональ 45 градусов от нефтяной дыры.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdnb.png\" alt=\"ks8bdnb.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Носите защитную одежду, чтобы предотвратить травмы от ожогов.</p></div></div><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Кранкшафт должен быть полностью размагничен и тщательно очищен. Небольшие металлические частицы могут привести к повреждению двигателя.</p></div></div><p>Размагничивайте коленчатый вал.</p><p>Используйте пар для очистки коленчатого вала и нефтяных бурений.</p><p>Используйте легкое консервантное масло для смазки коленчатого вала, чтобы предотвратить ржавчину.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Используйте масло с тяжелым консервантом, если коленчатый вал ** не будет установлен немедленно. Защитите деталь крышкой, чтобы грязь не прилипала к маслу.</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks600gd.png\" alt=\"ks600gd.png\"></figure><h3>Твист и гниль осмотр</h3><p>Прямолинейность коленчатого вала определяется количеством общего количества и соседней журнальной строки.</p><p>Следующие определения помогут понять процедуру:</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/10600725.png\" alt=\"10600725.png\"></figure><ul><li>Журнал Runout: Верхнее значение индикатора (общий размах иглы) основного несущего журнала по мере вращения коленчатого вала происходит один полный оборот (360 градусов). Полный выпуск относится к максимальному дезертирству, принятому в журнале в центре.</li><li>Adjacent Journal Runout: Связь показаний верхнего индикатора основного несущего журнала, когда он вращается по общей оси с показанием верхнего индикатора соседнего журнала.</li></ul><p>Соседний журнал Runout часто называют этапным, несущим или журнальным выпуском.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdtb.png\" alt=\"ks8bdtb.png\"></figure><ul><li>Положение часов: Расположение журнала в верхней точке показаний индикатора. Сравните его угловое отношение с числом 1 коленчатый вал, как видно из передней части коленчатого вала. В этом примере штифт коленчатого вала находится в 8-часовом положении. Это и есть часовое положение измеряемого журнала.</li></ul><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdtc.png\" alt=\"ks8bdtc.png\"></figure><p>Измерение прямолинейности коленчатого вала с заданной точностью может быть достигнуто только в том случае, если коленчатый вал:</p><ul><li>Правильно поддерживается</li><li>находится в тепловом равновесии</li><li>Может быть плавно повернут.</li></ul><p>Эти требования могут быть выполнены путем измерения коленчатого вала при поддержке несущих оболочек в блоке цилиндров. Вращение коленчатого вала с такой компоновкой приведет к ошибкам в результате бокового и вертикального смещения, возникающим из-за кривизны и зазора в основных подшипниках.</p><h4>Измерительная среда</h4><ul><li>Измерение <b> должно</b> проводиться в помещении с контролируемой температурой при температуре 20°C [68°F ] +/- 1 градус.</li><li>Измеряемый коленчатый вал должен храниться в этой комнате не менее двадцати четырех часов, чтобы коленчатый вал мог стабилизироваться при комнатной температуре.</li><li>Температура коленчатого вала ** должна быть проверена до начала измерений и записана на рабочем листе данных измерений, включенном в этот документ. См. рабочий лист данных измерений, раздел 1.8. ниже.</li></ul><h4>Настройка измерения</h4><ul><li>Таблица измерения ** должна быть оценена как поддерживающая по меньшей мере 450 кг [992 фунт ] и обеспечивающая стабильную плоскую поверхность, которая позволяет V-блокам быть выровнены и закреплены с коленчатым валом в центре линии в прямом горизонтальном положении.</li></ul><p>Рекомендуется использовать гранитную таблицу измерения и роликовые V-блоки. См. рисунок 1. Роллерные V-блоки имеют более низкое сопротивление качению, чем стандартные V-блоки при вращении коленчатого вала во время процесса измерения.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01k00101.png\" alt=\"01k00101.png\"></figure><p>Рисунок 1.</p><h4>Рисунок 1: Краншафт на V-блоках Roller</h4><ul><li>Моторизованный привод предпочтительно использовать для плавного вращения коленчатого вала на полных 360 градусов вращения. Прямое ручное вращение ** должно быть сделано очень осторожно, чтобы обеспечить плавное движение, необходимое для последовательных измерений.</li><li>Высота V-блоков <b> должна быть равна (Z-оси). Разница в высоте между V-блоками </b> должна быть намного меньше, чем определенная допуском часть.</li></ul><p>Пример: Если прямая спецификация составляет менее 0,06 мм [0,002 в ], то разница в высоте <b> должна быть 0,01 мм [0,04 в ] или меньше. Высота V-блоков </b> должна быть проверена в точках контакта V-блоков с журналом коленчатого вала с использованием калиброванного вала или бара. Измерения могут быть сделаны с помощью механического индикатора циферблата или электронной системы точного измерения.</p><ul><li>Используемое измерительное устройство должно иметь действительный сертификат калибровки и должно иметь разрешение, повторяемость и точность (отношение реального размера к тому, что указывает измерительное устройство), соответствующие оцениваемой спецификации прямолинейности.</li></ul><p>Поместите два V-блока на плоскую поверхность. Поддерживайте коленчатый вал на V-блоках на главном журнале № 2 и главном журнале № 8, как показано.</p><p>Убедитесь, что коленчатый вал свободен только для вращения, без вертикального или бокового движения в результате зазора в роликах или раскачивания V-блоков.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01s00116.png\" alt=\"01s00116.png\"></figure><p>Используйте индикатор циферблата для позиционирования индикатора, чтобы ствол касался несущего журнала, измеряемого в центре журнала.</p><p>Точка измерения, выбранная **, должна использоваться для измерения всех журналов подшипников.</p><p>К50 коленчатый вал имеет девять основных несущих журналов (не показаны).</p><p>Кранчхейт K38 имеет семь основных носителей, как показано на рисунке.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdte.png\" alt=\"ks8bdte.png\"></figure><p>Поверните коленчатый вал и измерьте верхнюю показания индикатора в каждом несущем журнале. Запишите значение и положение часов для каждого журнала.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdtf.png\" alt=\"ks8bdtf.png\"></figure><p>Проверьте номер детали, чтобы определить, является ли коленчатый вал полностью затвердевшим типом филе или не полностью затвердевшим типом филе. См. процедуру 001-999 в разделе F.</p><p>Полностью затвердевший или застреленный коленчатый вал <b> должен быть выброшен, если общий объем выбросов </b> не** в пределах спецификаций. Кранкшафт, который не имеет филе лечения, может быть выпрямлен. См. Руководство по альтернативному ремонту, Вестник 3379035.</p><p>Обсуждение Crankshaft Total Runout</p><p>Сравните результаты с спецификациями.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Crankshaft Total Runout (альбом)</th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td></td><td>мм</td><td></td><td>в</td><td></td></tr><tr><td>Двигатель K38</td><td></td><td>0.203</td><td>Макс</td><td>0.0081</td></tr><tr><td>Двигатель K50</td><td></td><td>0.267</td><td>Макс</td><td>0.0105</td></tr></tbody></table></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/10600725.png\" alt=\"10600725.png\"></figure><p>Определите ранжирование Adjacent Journal:</p><p>Пример иллюстрирует следующие сюжетные точки.</p><p>Для каждого журнала нарисуйте значение показаний верхнего индикатора в его положении часов на полярной диаграмме, проиллюстрированной на следующей странице.</p><p>Конечные журналы, поддерживаемые V-блоками **, должны быть расположены в центре диаграммы.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Журналист</th><th>Лучший индикатор показаний</th><th>Положение часов</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>0</td></tr><tr><td>2</td><td>0.0021</td><td>12</td></tr><tr><td>3</td><td>0.0030</td><td>12</td></tr><tr><td>4</td><td>0.0039</td><td>1</td></tr></tbody></table></div><p>Проведите прямую линию между начерченными точками (от журнала № 1 до номера 2 и от номера 2 до номера 3), пока все журналы не будут нанесены на график.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8bdtg.png\" alt=\"ks8bdtg.png\"></figure><p>Чтобы определить смежную полосу журнала, измерьте длину строки от каждого журнала до соответствующей точки журнала.</p><p>Иллюстрированный в качестве примера журнал номер 3 - номер 4 составляет 5,1 мм [2 in]. Это представляет собой беговую полосу 0,051 мм [0,002 в].</p><p>Запишите смежную полосу журнала для каждого несущего журнала. Сравните соседний выпуск журнала со спецификациями.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Обсуждение JOJNAL RUNUT</th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td></td><td>мм</td><td></td><td>в</td><td></td></tr><tr><td>Полностью закаленный Фильет</td><td></td><td>0.089</td><td>Макс</td><td>0.0035</td></tr><tr><td>Неполностью закаленный Фильет</td><td></td><td>0.089</td><td>Макс</td><td>0.0035</td></tr></tbody></table></div><p>Заменить коленчатый вал, если какое-либо измерение <b> не</b> в пределах спецификаций.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01400348.png\" alt=\"01400348.png\"></figure><p>Полярная диаграмма</p><p>Шкала 1 дюйм = 0,001 дюйм и 1 мм = 0,001 мм</p><p>Маленькие выпускные - 0,1 дюйма = 0,0001 дюйма.</p><h3>Установка</h3><p>Установите опору подшипника тяги коленчатого вала на блок цилиндров.</p><p>Затяните шесть болтов и замков шайбы в последовательности, показанной на иллюстрации.</p><div class=\"callout tip\"><div class=\"callout-head\"><span class=\"callout-ico\">🔧</span>Момент затяжки</div><div class=\"callout-body\"><p>60 Н·м [44 фунт-фут]</p></div></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/01400689.png\" alt=\"01400689.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Масса этого узла больше 23 кг [50 фунтов]. Чтобы предотвратить серьезные травмы, обязательно обратитесь за помощью или используйте соответствующее подъемное оборудование, чтобы поднять этот компонент или сборку.</p></div></div><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Завершите установку верхнего основного подшипника перед установкой коленчатого вала.<a class=\"lnk doc\" href=\"#/doc/28-001-006-tr\">См. процедуру 001-006 в разделе 1.</a></p></div></div><p>Используйте безмятежную ткань. Очистите журналы с коленчатым валом.</p><div class=\"callout note\"><div class=\"callout-head\"><span class=\"callout-ico\">i</span>Примечание</div><div class=\"callout-body\"><p>Конец коленчатого вала с шестерней, которая имеет наименьший диаметр <b>, должен </b> указывать на переднюю часть блока.</p></div></div><p>Установить коленчатый вал.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6shha.png\" alt=\"ks6shha.png\"></figure><h3>Завершающие операции</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Масса этого узла больше 23 кг [50 фунтов]. Чтобы предотвратить серьезные травмы, обязательно обратитесь за помощью или используйте соответствующее подъемное оборудование, чтобы поднять этот компонент или сборку.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Аккумуляторные батареи выделяют взрывоопасные газы. Чтобы снизить риск травмы, перед обслуживанием аккумуляторных батарей обязательно проветрите помещение. Чтобы снизить риск искрения, минусовой (-) провод аккумуляторной батареи снимайте первым, а подсоединяйте последним.</p></div></div><ul><li>Установите подшипники тяги.<a class=\"lnk doc\" href=\"#/doc/28-001-007-tr\">См. процедуру 001-007 в разделе 1.</a></li><li>Установите основные подшипниковые колпачки.<a class=\"lnk doc\" href=\"#/doc/28-001-006-tr\">См. процедуру 001-006 в разделе 1.</a></li><li>Установите головку цилиндра.<a class=\"lnk doc\" href=\"#/doc/28-002-004-tr\">См. процедуру 002-004 в разделе 2.</a>.</li><li>Установите поршень и соединительную сборку стержня.<a class=\"lnk doc\" href=\"#/doc/28-001-054-tr\">См. процедуру 001-054 в разделе 1.</a></li><li>Установите шатуны.<a class=\"lnk doc\" href=\"#/doc/28-001-054-tr\">См. процедуру 001-054 в разделе 1.</a></li><li>Установите переднюю крышку передних передач.<a class=\"lnk doc\" href=\"#/doc/28-001-031-tr\">См. процедуру 001-031 в разделе 1.</a></li><li>Установите корпус маховика.<a class=\"lnk doc\" href=\"#/doc/28-016-006-tr\">См. процедуру 016-006 в разделе 16.</a></li><li>Установите маховик, если его удалите.<a class=\"lnk doc\" href=\"#/doc/28-016-005-tr\">См. процедуру 016-005 в разделе 16.</a></li><li>Установите флешлейт, если он удален.<a class=\"lnk doc\" href=\"#/doc/28-016-004-tr\">См. процедуру 016-004 в разделе 16.</a></li><li>Удалите двигатель из подставки двигателя и установите.<a class=\"lnk doc\" href=\"#/doc/28-000-002-tr\">См. процедуру 000-002 в разделе 0.</a></li><li>Удалите подшипники тяги.<a class=\"lnk doc\" href=\"#/doc/28-001-007-tr\">См. процедуру 001-007 в разделе 1.</a></li><li>Установите адаптер масляной поддона.<a class=\"lnk doc\" href=\"#/doc/28-007-027-tr\">См. процедуру 007-027 в разделе 7.</a></li><li>Установите масляную всасывающую трубку. См. процедуру 007-035 в разделе 7.</li><li>Установите новые фильтры полного потока.<a class=\"lnk doc\" href=\"#/doc/28-007-013-tr\">См. процедуру 007-013 в разделе 7.</a></li><li>Заполните двигатель чистым моторным маслом 15W-40. См. процедуру 007-037 в разделе 7.</li><li>Подключите подачу воздуха/газа к воздухозаборнику, если он оборудован.<a class=\"lnk doc\" href=\"#/doc/102-012-022\">См. процедуру 012-022 в разделе 12.</a></li><li>Подсоедините аккумуляторные батареи. См. сервисную документацию изготовителя оборудования.</li><li>Управляйте двигателем. Проверьте на отсутствие утечек.</li></ul>","28-001-019-tr":"<h3>Разборка</h3><p>Удалите передачу <b>только </b>*, когда коленчатый вал или передача повреждены.</p><p>Используйте челюсть съёмника, Часть Номер 3375835 и мостовую сборку, Часть Номер 3375834.</p><p>Набор Crankshaft Gear Puller Kit, номер детали 3375840, содержит челюсть съёмника и мостовые сборки, необходимые для всех моделей двигателей Cummins®.</p><p>Установите челюсть съёмника и мостовую сборку.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8gema.png\" alt=\"ks8gema.png\"></figure><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не превышайте 475 Н•м [350 футов-лб] крутящего момента при повороте винта съёмника на челюсти съёмника или челюсть сломается.</p></div></div><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не используйте режущий факел. Высокая температура повредит шестерню.</p></div></div><p>Используйте моторное масло. Смазать винт съёмника.</p><p>Тепло может быть применено, чтобы помочь удалить передачу.</p><p>Держите прыжок устойчиво. Поверните винт съёмника. Снимите шестерёнку.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8gemb.png\" alt=\"ks8gemb.png\"></figure><p>Удалите ключ.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8kema.png\" alt=\"ks8kema.png\"></figure><h3>Очистка и проверка при повторном использовании</h3><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При очистке растворителями, кислотами и щелочными составами соблюдайте указания их изготовителя. Работайте в защитных очках и защитной одежде, чтобы снизить риск травмы.</p></div></div><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>При работе со сжатым воздухом применяйте защиту глаз и лица. Разлетающиеся частицы и грязь могут привести к травме.</p></div></div><p>Используйте камень. Польский внешний диаметр. Удалите любые мелкие царапины, заусеницы или небольшие канавки.</p><p>Чистый с растворителем. Просушите сжатым воздухом.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8kema.png\" alt=\"ks8kema.png\"></figure><p>Измерьте внешний диаметр.</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Crankshaft Outside Diameter (Местоположение)</th><th></th><th></th></tr></thead><tbody><tr><td>мм</td><td></td><td>в</td></tr><tr><td>111.25</td><td>Мин</td><td>4.380</td></tr><tr><td>111.28</td><td>Макс</td><td>4.381</td></tr></tbody></table></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks800ta.png\" alt=\"ks800ta.png\"></figure><p>Измерить внутренний диаметр</p><div class=\"tw\"><table class=\"doc-table\"><thead><tr><th>Передний коленчатый вал Gear Inside Diameter</th><th></th><th></th></tr></thead><tbody><tr><td>мм</td><td></td><td>в</td></tr><tr><td>111.165</td><td>Мин</td><td>4.3766</td></tr><tr><td>111.195</td><td>Макс</td><td>4.3778</td></tr></tbody></table></div><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks6geta.png\" alt=\"ks6geta.png\"></figure><h3>Сборка</h3><p>Установите новый ключ.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8keha.png\" alt=\"ks8keha.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Чтобы уменьшить возможность сильных ожогов, надевайте защитные перчатки при установке нагретого коленчатого вала.</p></div></div><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>При нагревании коленчатого вала не превышайте заданное время или температуру. Повреждение зубчатой валовой передачи и зубчатой передачи коленчатого вала приведет к повреждению.</p></div></div><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Не пытайтесь установить коленчатый вал без тепла. Повреждение зубчатой валовой передачи и зубчатой передачи коленчатого вала приведет к повреждению.</p></div></div><p>Используйте духовку. Настройте температуру до 232 ° C [450° F]. Нагрейте шестерню в духовке минимум на 1 час, максимум на 6 часов. Внутренний диаметр шестерни станет больше и упростит установку шестерни на коленчатом валу.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/dp8gewa.png\" alt=\"dp8gewa.png\"></figure><div class=\"callout danger\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОПАСНО</div><div class=\"callout-body\"><p>Чтобы уменьшить возможность сильных ожогов, надевайте защитные перчатки при установке нагретого коленчатого вала.</p></div></div><div class=\"callout warning\"><div class=\"callout-head\"><span class=\"callout-ico\">⚠</span>ОСТОРОЖНО</div><div class=\"callout-body\"><p>Позвольте воздуху охлаждать передачу. Не используйте воду или масло, чтобы уменьшить время охлаждения. Это может привести к треску шестерни.</p></div></div><p>Используйте Lubriplate® Number105 или эквивалент. Смазать внешний диаметр коленчатого вала в месте расположения зубчатой передачи.</p><p>Уберите шестерёнку из духовки.</p><p>Знаки времени на шестерне коленчатого вала ** должны быть видны спереди коленчатого вала после установки шестерни.</p><p>Ключевой путь ** должен быть выровнен с ключом в шестерене. Установите передачу.</p><figure class=\"fig\"><img loading=\"lazy\" src=\"assets/figures/ks8geha.png\" alt=\"ks8geha.png\"></figure>"};
